const STATE_RDPS_SCHEMA_VERSION: u16 = 1;
const TARGET_VULNERABILITY_RDPS_SCHEMA_VERSION: u16 = 4;
/// Bump whenever the projector's operation order, window semantics, stacking,
/// or integer/rational calculation changes independently of the bundled data.
const STATE_RDPS_PROJECTOR_ALGORITHM_REVISION: &str = "bpsr-state-rdps-projector.v46";
// Current-build Life Wave static identity. The child is a refreshable
// five-second recipient status produced by module family 2404. Its secondary-
// stat marginal is not promoted yet; these constants authorize only trigger
// ownership/timer tracking and explicit incomplete-rDPS signaling.
const LIFE_WAVE_SOURCE_TYPE_ID: i32 = 1;
const LIFE_WAVE_SOURCE_CONFIG_ID: i64 = 2_302_420;
const LIFE_WAVE_EFFECT_ID: i64 = 2_302_421;
const LIFE_WAVE_DURATION_MILLIS: u64 = 5_000;
const LIFE_WAVE_MODULE_EFFECT_ID: i32 = 2_404;
const LIFE_WAVE_ALLOWED_MODULE_CONFIG_IDS: [i32; 12] = [
    5_500_101, 5_500_102, 5_500_103, 5_500_104, 5_500_201, 5_500_202, 5_500_203, 5_500_204,
    5_500_301, 5_500_302, 5_500_303, 5_500_304,
];
const REMOTE_FACTOR_BUCKET_MICROS: u64 = 5_000_000;
const REMOTE_FACTOR_NEAREST_BUCKET_LIMIT: u64 = 6;
const REMOTE_FACTOR_MAX_DISTINCT_AMOUNTS: usize = 96;
const REMOTE_FACTOR_MAX_MECHANIC_GROUPS: usize = 4_096;
const LIVE_REMOTE_FACTOR_EVIDENCE_HORIZON_MICROS: u64 =
    REMOTE_FACTOR_BUCKET_MICROS * REMOTE_FACTOR_NEAREST_BUCKET_LIMIT;
// A 20-player encounter can exceed 4,096 eligible hits inside the 30-second
// remote-factor evidence horizon. Keep the queue bounded, but size it for the
// packet ceiling of a dense raid rather than silently evicting ordinary raid
// traffic. At the current entry sizes both queues together remain well below
// 64 MiB at their hard limits.
const LIVE_DEFERRED_TEAM_LUCK_LIMIT: usize = 262_144;
const LIVE_DEFERRED_REMOTE_HARMONY_LIMIT: usize = 262_144;
const LIVE_FULL_BLOOM_WINDOW_LIMIT: usize = 4_096;
// Kept per effect so unrelated paired-output rules cannot starve one another.
// This remains a hard memory bound; one observation can belong only to a
// runtime-enabled effect and each group retains at most the bounded rows below.
const REMOTE_PAIRED_OUTPUT_MAX_MECHANIC_GROUPS_PER_EFFECT: usize = 65_536;
const REMOTE_HARMONY_MAX_OBSERVATIONS_PER_STATE: usize = 64;

static STATE_RDPS_FORMULA_IDENTITY: OnceLock<String> = OnceLock::new();

/// Content identity for every production input consumed by the state rDPS
/// projector plus its calculation algorithm. Localized presentation catalogs
/// are deliberately excluded because numeric effect and build identity are the
/// runtime authority.
pub fn state_damage_contribution_formula_identity() -> &'static str {
    STATE_RDPS_FORMULA_IDENTITY
        .get_or_init(|| {
            let mut hasher = Sha256::new();
            for (label, content) in [
                (
                    "algorithm_revision",
                    STATE_RDPS_PROJECTOR_ALGORITHM_REVISION.as_bytes(),
                ),
                ("crate_version", env!("CARGO_PKG_VERSION").as_bytes()),
                (
                    "rdps-formula-runtime.v1.json",
                    include_bytes!("../game-data/runtime/rdps-formula-runtime.v1.json").as_slice(),
                ),
                (
                    "rdps-formula-runtime-overrides.v1.json",
                    include_bytes!("../game-data/runtime/rdps-formula-runtime-overrides.v1.json")
                        .as_slice(),
                ),
                (
                    "external-state-rdps.v1.json",
                    include_bytes!("../game-data/runtime/external-state-rdps.v1.json").as_slice(),
                ),
                (
                    "external-target-vulnerability-rdps.v2.json",
                    include_bytes!(
                        "../game-data/runtime/external-target-vulnerability-rdps.v2.json"
                    )
                    .as_slice(),
                ),
                (
                    "damage-stage-rdps.v1.json",
                    include_bytes!("../game-data/runtime/damage-stage-rdps.v1.json").as_slice(),
                ),
            ] {
                hasher.update((label.len() as u64).to_le_bytes());
                hasher.update(label.as_bytes());
                hasher.update((content.len() as u64).to_le_bytes());
                hasher.update(content);
            }
            format!("sha256:{:x}", hasher.finalize())
        })
        .as_str()
}

/// Stable evidence contract for calculating another player's rDPS.
///
/// Remote character snapshots are optional presentation and explanation
/// evidence. They are deliberately not calculation inputs: another player's
/// exact equipment, factor tree, levels, and other private loadout details are
/// not guaranteed to be present in this client's packet stream. The live
/// projector instead requires the server-observed provider/recipient window,
/// the applied runtime state, and an exact damage counterfactual.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub struct RemoteRdpsEvidencePolicy {
    pub build_snapshot_required: bool,
    pub character_level_required: bool,
    pub exact_equipment_required: bool,
    pub exact_factor_tree_required: bool,
    pub provider_recipient_window_required: bool,
    pub applied_runtime_magnitude_required: bool,
    pub exact_counterfactual_formula_required: bool,
    pub retain_damage_when_unresolved: bool,
}

/// The authoritative remote-player evidence policy shared by live, history,
/// submission, and audit consumers of the BPSR rDPS projector.
pub const fn remote_rdps_evidence_policy() -> RemoteRdpsEvidencePolicy {
    RemoteRdpsEvidencePolicy {
        build_snapshot_required: false,
        character_level_required: false,
        exact_equipment_required: false,
        exact_factor_tree_required: false,
        provider_recipient_window_required: true,
        applied_runtime_magnitude_required: true,
        exact_counterfactual_formula_required: true,
        retain_damage_when_unresolved: true,
    }
}

/// Effect IDs currently enabled by the packet-state projector. This list is
/// build-scoped and contains only mechanics whose provider, recipient, packet
/// state, and exact integer or explicitly versioned exact-rational observed-
/// damage attribution are proven.
pub fn proven_state_damage_contribution_effect_ids() -> Result<Vec<i64>, String> {
    let runtime = rdps_runtime_config()?;
    let mut effect_ids = Vec::new();
    effect_ids.extend(
        state_rdps_catalog()?
            .rules
            .iter()
            .map(|rule| rule.effect_id),
    );
    if runtime.runtime_promotion_allowed() {
        effect_ids.push(runtime.team_luck.effect_id);
        effect_ids.extend(
            target_vulnerability_rdps_catalog()?
                .rules
                .iter()
                .map(|rule| rule.effect_id),
        );
    }
    effect_ids.extend_from_slice(runtime.target_vulnerability_runtime_transfer_effect_ids());
    if runtime.effect_runtime_transfer_enabled(runtime.team_luck.effect_id) {
        effect_ids.push(runtime.team_luck.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.functional_amp.effect_id) {
        effect_ids.push(runtime.functional_amp.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.mechanical_power.effect_id) {
        effect_ids.push(runtime.mechanical_power.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.harmony_grace.effect_id) {
        effect_ids.push(runtime.harmony_grace.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.stat_resonance.effect_id) {
        effect_ids.push(runtime.stat_resonance.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.fiery_battle_will.effect_id) {
        effect_ids.push(runtime.fiery_battle_will.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.encore.effect_id) {
        effect_ids.push(runtime.encore.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.highland_blood.effect_id) {
        effect_ids.push(runtime.highland_blood.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.inspiration.effect_id) {
        effect_ids.push(runtime.inspiration.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.inspiration.full_bloom_effect_id) {
        effect_ids.push(runtime.inspiration.full_bloom_effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.endless_mind.effect_id) {
        effect_ids.push(runtime.endless_mind.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.arcane_time_decree.effect_id) {
        effect_ids.push(runtime.arcane_time_decree.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.thunder_roar.effect_id) {
        effect_ids.push(runtime.thunder_roar.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.poison_explosion_vulnerability.effect_id) {
        effect_ids.push(runtime.poison_explosion_vulnerability.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.celestial_guardian_vulnerability.effect_id) {
        effect_ids.push(runtime.celestial_guardian_vulnerability.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.critical_cold.effect_id) {
        effect_ids.push(runtime.critical_cold.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.synergy_crit_field.effect_id) {
        effect_ids.push(runtime.synergy_crit_field.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.element_sharing.effect_id) {
        effect_ids.push(runtime.element_sharing.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.enhanced_synergy.effect_id) {
        effect_ids.push(runtime.enhanced_synergy.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.blessing.effect_id) {
        effect_ids.push(runtime.blessing.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.synergy_luck_field.effect_id) {
        effect_ids.push(runtime.synergy_luck_field.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.coordinated_strike.effect_id) {
        effect_ids.push(runtime.coordinated_strike.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.all_class_aura.effect_id) {
        effect_ids.push(runtime.all_class_aura.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.tactical_blessing.effect_id) {
        effect_ids.push(runtime.tactical_blessing.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.attribute_transfer.effect_id) {
        effect_ids.push(runtime.attribute_transfer.effect_id);
    }
    if runtime.effect_runtime_transfer_enabled(runtime.inspire.effect_id) {
        effect_ids.push(runtime.inspire.effect_id);
    }
    effect_ids.sort_unstable();
    effect_ids.retain(|effect_id| {
        *effect_id != runtime.thunderwind.effect_id
            && *effect_id != runtime.thunderwind.child_effect_id
    });
    effect_ids.dedup();
    Ok(effect_ids)
}

/// Exact effect IDs available only to the offline target-vulnerability
/// candidate audit. These IDs are intentionally separate from
/// [`proven_state_damage_contribution_effect_ids`]: listing a reviewed
/// candidate here does not grant production formula, runtime, UI, or provider
/// credit authority.
pub fn target_vulnerability_candidate_effect_ids() -> Result<Vec<i64>, String> {
    let mut effect_ids = target_vulnerability_rdps_catalog()?
        .rules
        .iter()
        .map(|rule| rule.effect_id)
        .collect::<Vec<_>>();
    effect_ids.sort_unstable();
    effect_ids.dedup();
    Ok(effect_ids)
}

