    fn observe_attribute_transfer_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let config = &self.runtime.attribute_transfer;
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        match status.state {
            StatusState::Removed | StatusState::Consumed => {
                self.attribute_transfer_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || key.effect_id != config.effect_id
                        || instance_id.is_some_and(|instance| key.instance_id != Some(instance))
                });
            }
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked => {
                let key = FormulaStatusKey {
                    target_actor_id,
                    source_actor_id: status.source.map(|source| source.actor_id.0).unwrap_or(0),
                    effect_id: status.effect.0,
                    instance_id,
                };
                if key.source_actor_id == 0
                    || key.instance_id.is_none()
                    || status.level != Some(config.required_level)
                    || status.stacks != Some(config.required_stacks)
                    || status.duration_millis != Some(config.duration_millis)
                {
                    self.attribute_transfer_windows.retain(|existing, _| {
                        existing.target_actor_id != target_actor_id
                            || instance_id
                                .is_some_and(|instance| existing.instance_id != Some(instance))
                    });
                    self.formula_statuses.retain(|existing, _| {
                        existing.effect_id != config.effect_id
                            || existing.target_actor_id != target_actor_id
                            || instance_id
                                .is_some_and(|instance| existing.instance_id != Some(instance))
                    });
                    return;
                }
                let Some(expires_at_observed_micros) =
                    observed_micros.checked_add(config.duration_millis.saturating_mul(1_000))
                else {
                    self.attribute_transfer_windows.remove(&key);
                    return;
                };
                // A true refresh of the exact same instance retains its lane.
                // New instances remain unbound until their adjacent final-stat
                // transition supplies the missing branch identity.
                let prior_lane = (status.state == StatusState::Refreshed)
                    .then(|| {
                        self.attribute_transfer_windows
                            .get(&key)
                            .and_then(|window| window.lane)
                    })
                    .flatten();
                self.attribute_transfer_windows.insert(
                    key,
                    AttributeTransferWindow {
                        lifecycle: FormulaStatusWindow {
                            opened_observed_micros: observed_micros,
                            expires_at_observed_micros,
                        },
                        lane: prior_lane,
                    },
                );
            }
        }
    }

    fn observe_fatal_spiral_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        if let Some(wire) = self.current_wire {
            self.fatal_spiral_transition_wires
                .insert(target_actor_id, wire);
        }
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);

        if active {
            let Some(provider) = status.source else {
                return;
            };
            let provider_actor_id = provider.actor_id.0;
            self.fatal_spiral_windows.insert(FatalSpiralWindowKey {
                target_actor_id,
                target_entity_uuid: status.target.entity_uuid.0,
                provider_actor_id,
                provider_entity_uuid: provider.entity_uuid.0,
                instance_id,
            });
            self.fatal_spiral_transitions
                .entry(target_actor_id)
                .or_default()
                .push(FixedPointFamilyTransition {
                    provider_actor_id,
                    provider_entity_uuid: provider.entity_uuid.0,
                    active: true,
                });
            return;
        }

        let mut removed_providers = self
            .fatal_spiral_windows
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id)
            .filter(|key| instance_id.is_none() || key.instance_id == instance_id)
            .filter(|key| {
                status.source.is_none_or(|provider| {
                    key.provider_actor_id == provider.actor_id.0
                        && (provider.entity_uuid.0 == 0
                            || key.provider_entity_uuid == provider.entity_uuid.0)
                })
            })
            .map(|key| (key.provider_actor_id, key.provider_entity_uuid))
            .collect::<Vec<_>>();
        removed_providers.sort_unstable();
        removed_providers.dedup();
        self.fatal_spiral_windows.retain(|key| {
            !(key.target_actor_id == target_actor_id
                && removed_providers.contains(&(key.provider_actor_id, key.provider_entity_uuid))
                && (instance_id.is_none() || key.instance_id == instance_id))
        });
        self.fatal_spiral_transitions
            .entry(target_actor_id)
            .or_default()
            .extend(removed_providers.into_iter().map(
                |(provider_actor_id, provider_entity_uuid)| FixedPointFamilyTransition {
                    provider_actor_id,
                    provider_entity_uuid,
                    active: false,
                },
            ));
    }

    fn observe_fatal_spiral_data_gap(&mut self, kind: DataGapKind) {
        if kind != DataGapKind::TcpGap {
            return;
        }
        // A real TCP gap can hide a status removal or provider transition.
        // Truncate every active lifecycle at the first such gap. Parser and
        // route failures do not prove missing transport bytes and therefore
        // do not invalidate an otherwise exact lifecycle.
        self.fatal_spiral_windows.clear();
        self.fatal_spiral_transition_wires.clear();
        self.fatal_spiral_transitions.clear();
        self.fatal_spiral_snapshot_targets.clear();
        for state in self.states.values_mut() {
            state.all_element.provider_basis_points.clear();
        }
        for state in self.staged_states.values_mut() {
            state.all_element.provider_basis_points.clear();
        }
    }

    fn observe_full_bloom_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        self.full_bloom_windows
            .retain(|_, window| observed_micros <= window.expires_at_observed_micros);
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active {
            let exact_identity = status
                .origin
                .map(|origin| (origin.source_type_id, origin.source_config_id))
                == Some((
                    self.runtime.inspiration.full_bloom_source_type_id,
                    self.runtime.inspiration.full_bloom_source_config_id,
                ))
                && status.level == Some(self.runtime.inspiration.full_bloom_required_level)
                && status.stacks == Some(self.runtime.inspiration.full_bloom_required_stacks)
                && status.duration_millis
                    == Some(self.runtime.inspiration.full_bloom_duration_millis);
            let Some(provider) = status.source.filter(|_| exact_identity) else {
                // An active row with incomplete identity supersedes any older
                // exact window for this target/instance. Do not carry stale
                // provider ownership through an unprovable refresh.
                self.full_bloom_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
                return;
            };
            let Some(expires_at_observed_micros) = status
                .duration_millis
                .and_then(|duration| duration.checked_mul(1_000))
                .and_then(|duration| observed_micros.checked_add(duration))
            else {
                return;
            };
            let key = EffectWindowKey {
                target_actor_id,
                provider_actor_id: provider.actor_id.0,
                instance_id,
            };
            if self.full_bloom_windows.len() >= LIVE_FULL_BLOOM_WINDOW_LIMIT
                && !self.full_bloom_windows.contains_key(&key)
            {
                // Fail closed as one unit instead of evicting a possibly
                // authoritative owner and silently preferring a newer row.
                self.full_bloom_windows.clear();
                return;
            }
            self.full_bloom_windows.insert(
                key,
                FullBloomWindow {
                    target_entity_uuid: status.target.entity_uuid.0,
                    provider_entity_uuid: provider.entity_uuid.0,
                    expires_at_observed_micros,
                },
            );
            return;
        }
        self.full_bloom_windows.retain(|key, window| {
            if key.target_actor_id != target_actor_id
                && (status.target.entity_uuid.0 == 0
                    || window.target_entity_uuid != status.target.entity_uuid.0)
            {
                return true;
            }
            if instance_id.is_some() && key.instance_id != instance_id {
                return true;
            }
            status.source.is_some_and(|provider| {
                key.provider_actor_id != provider.actor_id.0
                    || (provider.entity_uuid.0 != 0
                        && window.provider_entity_uuid != provider.entity_uuid.0)
            })
        });
    }

    fn clear_full_bloom_after_gap(&mut self, kind: DataGapKind) {
        if kind == DataGapKind::TcpGap {
            // A missing transport range can hide the 10-second terminal or a
            // provider rotation. Existing Inspiration instances retain their
            // sampled mode, but no later apply may reuse stale ownership.
            self.full_bloom_windows.clear();
        }
    }

    fn full_bloom_snapshot_for_inspiration_provider(
        &self,
        provider_actor_id: u64,
        provider_entity_uuid: i64,
        observed_micros: u64,
    ) -> (bool, Option<(u64, i64)>) {
        let mut matching = self.full_bloom_windows.iter().filter(|(key, window)| {
            (key.target_actor_id == provider_actor_id
                || (provider_entity_uuid != 0 && window.target_entity_uuid == provider_entity_uuid))
                && observed_micros <= window.expires_at_observed_micros
        });
        let Some((key, window)) = matching.next() else {
            return (false, None);
        };
        let snapshot = (
            self.actor_ancestry
                .actor_for_entity(window.provider_entity_uuid)
                .unwrap_or(key.provider_actor_id),
            window.provider_entity_uuid,
        );
        if matching.next().is_some() {
            // Presence still proves the 6/5 Inspiration mode, but ownership is
            // ambiguous, so only the base Inspiration component may transfer.
            (true, None)
        } else {
            (true, Some(snapshot))
        }
    }

    fn observe_inspiration_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let provider_actor_id = status.source.map(|source| source.actor_id.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active {
            let Some(provider_actor_id) = provider_actor_id else {
                if let Some(wire) = self.current_wire {
                    self.inspiration_transition_wires
                        .insert(target_actor_id, wire);
                }
                return;
            };
            let provider = status
                .source
                .expect("an active Inspiration window has a provider");
            let (provider_full_bloom, full_bloom_provider) = self
                .full_bloom_snapshot_for_inspiration_provider(
                    provider_actor_id,
                    provider.entity_uuid.0,
                    observed_micros,
                );
            self.inspiration_windows.insert(
                EffectWindowKey {
                    target_actor_id,
                    provider_actor_id,
                    instance_id,
                },
                InspirationWindow {
                    provider_full_bloom,
                    full_bloom_provider_actor_id: full_bloom_provider.map(|provider| provider.0),
                    full_bloom_provider_entity_uuid: full_bloom_provider.map(|provider| provider.1),
                    target_entity_uuid: status.target.entity_uuid.0,
                    provider_entity_uuid: provider.entity_uuid.0,
                    source_level: status.level,
                    origin_source_type_id: status.origin.map(|origin| origin.source_type_id),
                    origin_source_config_id: status.origin.map(|origin| origin.source_config_id),
                    expires_at_observed_micros: status.duration_millis.and_then(|duration| {
                        duration
                            .checked_mul(1_000)
                            .and_then(|duration| observed_micros.checked_add(duration))
                    }),
                },
            );
        } else {
            self.inspiration_windows.retain(|key, _| {
                if key.target_actor_id != target_actor_id {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider_actor_id) = provider_actor_id
                    && key.provider_actor_id != provider_actor_id
                {
                    return true;
                }
                false
            });
        }
        if let Some(wire) = self.current_wire {
            self.inspiration_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn observe_critical_cold_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let target_entity_uuid = status.target.entity_uuid.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let provider_actor_id = status.source.map(|source| source.actor_id.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        let exact_identity = status.level == Some(self.runtime.critical_cold.required_level)
            && status.stacks == Some(self.runtime.critical_cold.required_stacks)
            && status
                .origin
                .map(|origin| (origin.source_type_id, origin.source_config_id))
                == Some((
                    self.runtime.critical_cold.source_type_id,
                    self.runtime.critical_cold.source_config_id,
                ));

        if active && exact_identity {
            if let Some(provider) = status.source
                && provider != status.target
            {
                self.critical_cold_windows.insert(
                    EffectWindowKey {
                        target_actor_id,
                        provider_actor_id: provider.actor_id.0,
                        instance_id,
                    },
                    CriticalColdWindow {
                        target_entity_uuid,
                        provider_entity_uuid: provider.entity_uuid.0,
                    },
                );
            } else {
                // An active row without exact external ownership cannot keep
                // an older window eligible for the same recipient/instance.
                self.critical_cold_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
            }
        } else {
            self.critical_cold_windows.retain(|key, _| {
                if key.target_actor_id != target_actor_id {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider_actor_id) = provider_actor_id
                    && key.provider_actor_id != provider_actor_id
                {
                    return true;
                }
                false
            });
        }
        if let Some(wire) = self.current_wire {
            self.critical_cold_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn observe_endless_mind_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let target_entity_uuid = status.target.entity_uuid.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        let exact_identity = status.level == Some(self.runtime.endless_mind.required_level)
            && status.stacks.is_some_and(|stacks| {
                (self.runtime.endless_mind.minimum_stacks
                    ..=self.runtime.endless_mind.maximum_stacks)
                    .contains(&stacks)
            })
            && status
                .origin
                .map(|origin| (origin.source_type_id, origin.source_config_id))
                == Some((
                    self.runtime.endless_mind.source_type_id,
                    self.runtime.endless_mind.source_config_id,
                ));

        if active && exact_identity {
            if let Some(provider) = status.source
                && provider != status.target
            {
                self.endless_mind_windows.insert(
                    EffectWindowKey {
                        target_actor_id,
                        provider_actor_id: provider.actor_id.0,
                        instance_id,
                    },
                    EndlessMindWindow {
                        target_entity_uuid,
                        provider_entity_uuid: provider.entity_uuid.0,
                        stacks: status
                            .stacks
                            .expect("an exact Endless Mind lifecycle has stacks"),
                    },
                );
            } else {
                // An incomplete or self-owned refresh supersedes any older
                // exact external owner for this lifecycle instance.
                self.endless_mind_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
            }
        } else {
            self.endless_mind_windows.retain(|key, window| {
                if key.target_actor_id != target_actor_id
                    && (target_entity_uuid == 0 || window.target_entity_uuid != target_entity_uuid)
                {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                status.source.is_some_and(|provider| {
                    key.provider_actor_id != provider.actor_id.0
                        || (provider.entity_uuid.0 != 0
                            && window.provider_entity_uuid != provider.entity_uuid.0)
                })
            });
        }
        if let Some(wire) = self.current_wire {
            self.endless_mind_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn clear_endless_mind_after_gap(&mut self, kind: DataGapKind) {
        if kind == DataGapKind::TcpGap {
            self.endless_mind_windows.clear();
            self.endless_mind_transition_wires.clear();
        }
    }

    fn observe_arcane_time_decree_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let target_actor_id = status.target.actor_id.0;
        let target_entity_uuid = status.target.entity_uuid.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        if let Some(wire) = self.current_wire {
            self.arcane_time_decree_transition_wires
                .insert(target_actor_id, wire);
        }
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active {
            let exact_identity = status.level
                == Some(self.runtime.arcane_time_decree.required_effect_level)
                && status.stacks == Some(self.runtime.arcane_time_decree.required_stacks)
                && status.duration_millis == Some(self.runtime.arcane_time_decree.duration_millis)
                && target_entity_uuid != 0;
            let Some(provider) = status.source.filter(|_| exact_identity) else {
                self.arcane_time_decree_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
                return;
            };
            let provider_owner_actor_id = self.resolve_owner_actor_id(provider.actor_id.0);
            let Some(provider_owner_entity_uuid) = self
                .actor_ancestry
                .entity_for_actor(provider_owner_actor_id)
                .filter(|entity_uuid| *entity_uuid != 0)
            else {
                return;
            };
            if !self.active_players.contains(&provider_owner_actor_id)
                || !self
                    .arcane_time_decree_basis_points_by_provider_entity
                    .contains_key(&provider_owner_entity_uuid)
            {
                return;
            }
            let Some(expires_at_observed_micros) = self
                .runtime
                .arcane_time_decree
                .duration_millis
                .checked_mul(1_000)
                .and_then(|duration| observed_micros.checked_add(duration))
            else {
                return;
            };
            self.arcane_time_decree_windows.insert(
                EffectWindowKey {
                    target_actor_id,
                    provider_actor_id: provider.actor_id.0,
                    instance_id,
                },
                ArcaneTimeDecreeWindow {
                    target_entity_uuid,
                    provider_entity_uuid: provider.entity_uuid.0,
                    provider_owner_actor_id,
                    provider_owner_entity_uuid,
                    opened_observed_micros: observed_micros,
                    expires_at_observed_micros,
                },
            );
            return;
        }
        self.arcane_time_decree_windows.retain(|key, window| {
            if key.target_actor_id != target_actor_id
                || instance_id.is_some_and(|instance| key.instance_id != Some(instance))
            {
                return true;
            }
            status.source.is_some_and(|source| {
                key.provider_actor_id != source.actor_id.0
                    || (source.entity_uuid.0 != 0
                        && window.provider_entity_uuid != source.entity_uuid.0)
            })
        });
    }

    fn observe_thunder_roar_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let config = &self.runtime.thunder_roar;
        let target_actor_id = status.target.actor_id.0;
        let target_entity_uuid = status.target.entity_uuid.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);

        if active {
            let exact_shape = status.level == Some(config.required_effect_level)
                && status.stacks == Some(config.required_stacks)
                && status.duration_millis == Some(config.duration_millis)
                && target_entity_uuid != 0;
            let Some(source) = status.source.filter(|_| exact_shape) else {
                self.thunder_roar_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
                return;
            };
            self.actor_ancestry.observe_entity(status.target);
            self.actor_ancestry.observe_entity(source);
            let provider_owner_actor_id = self
                .actor_ancestry
                .resolve_actor_id_at(source.actor_id.0, observed_micros);
            let Some(provider_owner_entity_uuid) = self
                .actor_ancestry
                .entity_for_actor(provider_owner_actor_id)
                .filter(|entity_uuid| *entity_uuid != 0)
            else {
                return;
            };
            if !self.active_players.contains(&provider_owner_actor_id)
                || provider_owner_actor_id == target_actor_id
                || provider_owner_entity_uuid == target_entity_uuid
            {
                return;
            }
            let Some(expires_at_observed_micros) = config
                .duration_millis
                .checked_mul(1_000)
                .and_then(|duration| observed_micros.checked_add(duration))
            else {
                return;
            };
            self.thunder_roar_windows.insert(
                EffectWindowKey {
                    target_actor_id,
                    provider_actor_id: source.actor_id.0,
                    instance_id,
                },
                ThunderRoarWindow {
                    target_entity_uuid,
                    source_actor_id: source.actor_id.0,
                    source_entity_uuid: source.entity_uuid.0,
                    provider_owner_actor_id,
                    provider_owner_entity_uuid,
                    opened_observed_micros: observed_micros,
                    expires_at_observed_micros,
                },
            );
            return;
        }

        self.thunder_roar_windows.retain(|key, window| {
            let target_matches = key.target_actor_id == target_actor_id
                || (target_entity_uuid != 0 && window.target_entity_uuid == target_entity_uuid);
            let instance_matches =
                instance_id.is_none_or(|instance| key.instance_id == Some(instance));
            let source_matches = status.source.is_none_or(|source| {
                window.source_actor_id == source.actor_id.0
                    && (source.entity_uuid.0 == 0
                        || window.source_entity_uuid == source.entity_uuid.0)
            });
            !(target_matches && instance_matches && source_matches)
        });
    }

    fn observe_cooldown_action_state(
        &mut self,
        observed_micros: u64,
        cooldown: &rlogs_events::CooldownEvent,
    ) {
        let key = (cooldown.actor.actor_id.0, cooldown.ability.0);
        let exact = cooldown.actor.entity_uuid.0 != 0
            && cooldown.ability.0 > 0
            && cooldown
                .duration_millis
                .is_some_and(|duration| duration > 0)
            && cooldown
                .valid_duration_millis
                .is_none_or(|duration| duration > 0)
            && cooldown
                .valid_cooldown_time_millis
                .is_none_or(|duration| duration > 0)
            && cooldown
                .accelerate_cooldown_ratio_raw
                .is_some_and(|value| value >= 0);
        if !exact {
            self.cooldown_action_state.remove(&key);
            return;
        }
        self.cooldown_action_state.insert(
            key,
            CooldownActionState {
                actor_entity_uuid: cooldown.actor.entity_uuid.0,
                observed_micros,
                duration_millis: cooldown.duration_millis.unwrap_or_default(),
                accelerate_basis_points: i64::from(
                    cooldown.accelerate_cooldown_ratio_raw.unwrap_or_default(),
                ),
            },
        );
    }

    fn clear_arcane_time_decree_after_gap(&mut self, kind: DataGapKind) {
        if kind == DataGapKind::TcpGap {
            self.arcane_time_decree_windows.clear();
            self.arcane_time_decree_transition_wires.clear();
            self.cooldown_action_state.clear();
        }
    }

    fn clear_thunder_roar_after_gap(&mut self, kind: DataGapKind) {
        if kind == DataGapKind::TcpGap {
            self.thunder_roar_windows.clear();
        }
    }

    fn clear_critical_cold_after_gap(&mut self, kind: DataGapKind) {
        if kind == DataGapKind::TcpGap {
            self.critical_cold_windows.clear();
            self.critical_cold_transition_wires.clear();
            self.inspiration_recipient_dependency_entities.clear();
        }
    }

    fn observe_target_vulnerability_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let target_actor_id = status.target.actor_id.0;
        let effect_id = status.effect.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        if let Some(provider) = status.source {
            self.target_vulnerability_transitions
                .insert(TargetVulnerabilityTransitionKey {
                    target_actor_id,
                    provider_actor_id: provider.actor_id.0,
                    effect_id,
                });
        }
        match status.state {
            StatusState::Removed | StatusState::Consumed => {
                self.target_vulnerability_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || key.effect_id != effect_id
                        || instance_id.is_some_and(|instance| key.instance_id != Some(instance))
                });
            }
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked => {
                let Some(provider) = status.source else {
                    return;
                };
                let key = TargetVulnerabilityWindowKey {
                    target_actor_id,
                    provider_actor_id: provider.actor_id.0,
                    effect_id,
                    instance_id,
                };
                let expires_at_observed_micros = status
                    .duration_millis
                    .and_then(|duration| observed_micros.checked_add(duration.checked_mul(1_000)?));
                self.target_vulnerability_windows.insert(
                    key,
                    TargetVulnerabilityWindow {
                        expires_at_observed_micros,
                    },
                );
            }
        }
    }

    fn observe_team_luck_status(&mut self, status: &rlogs_events::StatusEvent) {
        let Some(provider) = status.source else {
            return;
        };
        let key = TeamLuckWindowKey {
            target_actor_id: status.target.actor_id.0,
            target_entity_uuid: status.target.entity_uuid.0,
            provider_actor_id: provider.actor_id.0,
            provider_entity_uuid: provider.entity_uuid.0,
            instance_id: status.instance_id.map(|instance| instance.0),
        };
        let active = match status.state {
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked => true,
            StatusState::Removed => false,
            // The canonical state means this exact effect instance was
            // consumed. Remaining stacks, when present, describe the event
            // payload; they do not keep the consumed instance alive.
            StatusState::Consumed => false,
        };
        if active {
            self.team_luck_windows.insert(key);
        } else {
            self.team_luck_windows.remove(&key);
        }
        // Attribute events from the same decoded wire are staged until the
        // following wire. Exclude every selected-effect wire, including a
        // refresh whose membership is unchanged, so damage can never combine
        // the new status payload with the previous attribute state.
        if let Some(wire) = self.current_wire {
            self.team_luck_transition_wires
                .insert(status.target.actor_id.0, wire);
        }
    }

    fn observe_functional_amp_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let target_entity_uuid = status.target.entity_uuid.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active {
            let Some(provider) = status.source else {
                if let Some(wire) = self.current_wire {
                    self.functional_amp_transition_wires
                        .insert(target_actor_id, wire);
                }
                return;
            };
            self.functional_amp_windows.insert(FunctionalAmpWindowKey {
                target_actor_id,
                target_entity_uuid,
                provider_actor_id: provider.actor_id.0,
                provider_entity_uuid: provider.entity_uuid.0,
                instance_id,
            });
        } else {
            let provider = status.source;
            self.functional_amp_windows.retain(|key| {
                if key.target_actor_id != target_actor_id
                    || key.target_entity_uuid != target_entity_uuid
                {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider) = provider {
                    if key.provider_actor_id != provider.actor_id.0
                        || key.provider_entity_uuid != provider.entity_uuid.0
                    {
                        return true;
                    }
                }
                false
            });
        }
        if let Some(wire) = self.current_wire {
            self.functional_amp_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn observe_mechanical_power_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active {
            let Some(provider) = status.source else {
                if let Some(wire) = self.current_wire {
                    self.mechanical_power_transition_wires
                        .insert(target_actor_id, wire);
                }
                return;
            };
            let window = EffectWindowKey {
                target_actor_id,
                provider_actor_id: provider.actor_id.0,
                instance_id,
            };
            if self.mechanical_power_windows.insert(window) {
                self.mechanical_power_primary_transition_witnesses
                    .remove(&window);
            }
        } else {
            let provider_actor_id = status.source.map(|source| source.actor_id.0);
            self.mechanical_power_windows.retain(|key| {
                if key.target_actor_id != target_actor_id {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider_actor_id) = provider_actor_id
                    && key.provider_actor_id != provider_actor_id
                {
                    return true;
                }
                false
            });
            self.mechanical_power_primary_transition_witnesses
                .retain(|key, _| self.mechanical_power_windows.contains(key));
        }
        // Entity attributes and the status lifecycle can be decoded from the
        // same wire frame with the attribute event first. Reconcile after the
        // lifecycle changes so the exact staged transition can name its
        // provider before the wire is committed.
        self.reconcile_mechanical_power_staged_state(target_actor_id);
        if let Some(wire) = self.current_wire {
            self.mechanical_power_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn reconcile_mechanical_power_staged_state(&mut self, target_actor_id: u64) {
        let Some(class_id) = self.recipient_class_id_for_actor(
            target_actor_id,
            &self.runtime.mechanical_power.recipient_rules,
        ) else {
            return;
        };
        let Some(recipient_rule) = self
            .runtime
            .mechanical_power
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == class_id)
            .cloned()
        else {
            return;
        };
        let desired =
            self.desired_mechanical_power_provider_percentages(target_actor_id, &recipient_rule);
        let Some(previous) = self
            .states
            .get(&target_actor_id)
            .and_then(|state| state.mechanical_primary_by_class.get(&class_id))
            .cloned()
        else {
            return;
        };
        let Some(current) = self
            .staged_states
            .get_mut(&target_actor_id)
            .and_then(|state| state.mechanical_primary_by_class.get_mut(&class_id))
        else {
            return;
        };

        debug_assert_eq!(recipient_rule.recipient_class_id, class_id);
        reconcile_external_percent_family(previous.raw_percent, current, &desired);
        reconcile_external_percent_family_from_exact_prior(&previous, current, &desired);
        let current = current.clone();
        self.record_mechanical_power_primary_transition_witness(
            target_actor_id,
            &previous,
            &current,
            &desired,
        );
    }

    fn observe_harmony_grace_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let provider_actor_id = status.source.map(|source| source.actor_id.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        );
        if active {
            let Some(provider) = status.source else {
                if let Some(wire) = self.current_wire {
                    self.harmony_grace_transition_wires
                        .insert(target_actor_id, wire);
                }
                return;
            };
            let window = EffectWindowKey {
                target_actor_id,
                provider_actor_id: provider.actor_id.0,
                instance_id,
            };
            if self.harmony_grace_windows.insert(window) {
                self.harmony_grace_primary_transition_witnesses
                    .remove(&window);
            }
            // A refresh starts a new packet-carried membership interval even
            // when the exact instance key is unchanged. Damage at this same
            // timestamp cannot be ordered against the refresh.
            self.harmony_grace_window_timing.insert(
                window,
                HarmonyGraceWindowTiming {
                    opened_observed_micros: observed_micros,
                    duration_millis: status.duration_millis,
                },
            );
        } else {
            let provider_targets = (status.state == StatusState::Consumed)
                .then(|| {
                    provider_actor_id.map(|provider_actor_id| {
                        self.harmony_grace_windows
                            .iter()
                            .filter(|key| key.provider_actor_id == provider_actor_id)
                            .map(|key| key.target_actor_id)
                            .collect::<HashSet<_>>()
                    })
                })
                .flatten();
            self.harmony_grace_windows.retain(|key| {
                // One Harmony activation is broadcast to the party, and the
                // server fans its Consumed lifecycle out as one row per
                // recipient. Damage for a later recipient can be ordered
                // between those duplicate rows. The first Consumed row is
                // therefore the exact provider-wide closure; Removed remains
                // a target-local lifecycle.
                if status.state == StatusState::Consumed {
                    return provider_actor_id != Some(key.provider_actor_id);
                }
                if key.target_actor_id != target_actor_id {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider_actor_id) = provider_actor_id
                    && key.provider_actor_id != provider_actor_id
                {
                    return true;
                }
                false
            });
            if let Some(provider_targets) = provider_targets {
                for provider_target in provider_targets {
                    self.reconcile_harmony_grace_staged_state(provider_target);
                    if let Some(wire) = self.current_wire {
                        self.harmony_grace_transition_wires
                            .insert(provider_target, wire);
                    }
                }
            }
            self.harmony_grace_primary_transition_witnesses
                .retain(|key, _| self.harmony_grace_windows.contains(key));
            self.harmony_grace_window_timing
                .retain(|key, _| self.harmony_grace_windows.contains(key));
        }
        // Attribute deltas and their status lifecycle can share a wire frame.
        // The attribute event is decoded first, so its staged state cannot yet
        // name the external provider. Reconcile that exact staged transition
        // after the status window changes instead of waiting for another
        // attribute packet (which may omit this family entirely).
        self.reconcile_harmony_grace_staged_state(target_actor_id);
        if let Some(wire) = self.current_wire {
            self.harmony_grace_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn reconcile_harmony_grace_staged_state(&mut self, target_actor_id: u64) {
        // The status description has no recipient-class condition. Reconcile
        // every listed primary family even when the recipient's class is not
        // yet known; class identity is needed only when damage later chooses
        // its own primary-to-Attack route.
        let recipient_rules = self.runtime.harmony_grace.recipient_rules.clone();
        let mut transition_candidates = Vec::new();
        for recipient_rule in recipient_rules {
            let class_id = recipient_rule.recipient_class_id;
            let desired =
                self.desired_harmony_grace_provider_percentages(target_actor_id, &recipient_rule);
            let Some(previous) = self
                .states
                .get(&target_actor_id)
                .and_then(|state| state.harmony_primary_by_class.get(&class_id))
                .cloned()
            else {
                continue;
            };
            let Some(current) = self
                .staged_states
                .get_mut(&target_actor_id)
                .and_then(|state| state.harmony_primary_by_class.get_mut(&class_id))
            else {
                continue;
            };

            reconcile_external_percent_family(previous.raw_percent, current, &desired);
            reconcile_external_percent_family_from_exact_prior(&previous, current, &desired);
            transition_candidates.push((previous, current.clone(), desired));
        }
        for (previous, current, desired) in transition_candidates {
            self.record_harmony_grace_primary_transition_witness(
                target_actor_id,
                &previous,
                &current,
                &desired,
            );
        }
    }

    fn observe_stat_resonance_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let Some(provider_actor_id) = status.source.map(|source| source.actor_id.0) else {
            self.invalidate_stat_resonance_target(target_actor_id);
            return;
        };
        if provider_actor_id == target_actor_id {
            self.invalidate_stat_resonance_target(target_actor_id);
            return;
        }
        let window = EffectWindowKey {
            target_actor_id,
            provider_actor_id,
            instance_id: status.instance_id.map(|instance| instance.0),
        };
        let transition = match status.state {
            StatusState::Applied => {
                if !self.stat_resonance_windows.insert(window) {
                    self.invalidate_stat_resonance_target(target_actor_id);
                    return;
                }
                StatResonanceTransition {
                    window,
                    applied: true,
                }
            }
            StatusState::Removed => {
                if !self.stat_resonance_windows.remove(&window) {
                    self.invalidate_stat_resonance_target(target_actor_id);
                    return;
                }
                StatResonanceTransition {
                    window,
                    applied: false,
                }
            }
            StatusState::Refreshed | StatusState::Stacked | StatusState::Consumed => {
                self.invalidate_stat_resonance_target(target_actor_id);
                return;
            }
        };
        if self
            .stat_resonance_pending_transitions
            .insert(target_actor_id, Some(transition))
            .is_some()
        {
            self.invalidate_stat_resonance_target(target_actor_id);
            return;
        }
        if let Some(wire) = self.current_wire {
            self.stat_resonance_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn invalidate_stat_resonance_target(&mut self, target_actor_id: u64) {
        self.stat_resonance_windows
            .retain(|key| key.target_actor_id != target_actor_id);
        self.stat_resonance_attack_witnesses
            .retain(|key, _| key.target_actor_id != target_actor_id);
        self.stat_resonance_pending_transitions
            .insert(target_actor_id, None);
        if let Some(wire) = self.current_wire {
            self.stat_resonance_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn reconcile_stat_resonance_staged_states(&mut self) {
        let pending = std::mem::take(&mut self.stat_resonance_pending_transitions);
        for (target_actor_id, transition) in pending {
            let Some(transition) = transition else {
                continue;
            };
            let has_status_confounder =
                self.formula_status_prior_values_current_wire
                    .keys()
                    .any(|key| {
                        key.target_actor_id == target_actor_id
                            && key.effect_id != self.runtime.stat_resonance.effect_id
                    });
            let has_unresolved_confounder = self
                .unresolved_status_windows
                .iter()
                .any(|key| key.target_actor_id == target_actor_id);
            let exact_window_count = self
                .stat_resonance_windows
                .iter()
                .filter(|key| key.target_actor_id == target_actor_id)
                .count();
            let expected_window_count = usize::from(transition.applied);
            if has_status_confounder
                || has_unresolved_confounder
                || exact_window_count != expected_window_count
                || !self
                    .active_players
                    .contains(&transition.window.provider_actor_id)
            {
                self.invalidate_stat_resonance_target(target_actor_id);
                continue;
            }
            let Some(previous) = self.states.get(&target_actor_id) else {
                self.invalidate_stat_resonance_target(target_actor_id);
                continue;
            };
            let Some(current) = self.staged_states.get(&target_actor_id) else {
                self.invalidate_stat_resonance_target(target_actor_id);
                continue;
            };
            let Some((lane, inactive_family, active_family)) =
                exact_single_attack_family_transition(previous, current, transition.applied)
            else {
                self.invalidate_stat_resonance_target(target_actor_id);
                continue;
            };
            let Some(final_attack_marginal) = active_family
                .final_value
                .checked_sub(inactive_family.final_value)
                .filter(|value| *value > 0)
            else {
                self.invalidate_stat_resonance_target(target_actor_id);
                continue;
            };
            let witness = StatResonanceAttackWitness {
                lane,
                active_family,
                final_attack_marginal,
            };
            if transition.applied {
                self.stat_resonance_attack_witnesses
                    .insert(transition.window, witness);
            } else {
                let removal_matches =
                    self.stat_resonance_attack_witnesses.get(&transition.window) == Some(&witness);
                self.stat_resonance_attack_witnesses
                    .remove(&transition.window);
                if !removal_matches {
                    self.invalidate_stat_resonance_target(target_actor_id);
                }
            }
        }
    }

    fn exact_fiery_battle_will_provider(&self, target_actor_id: u64) -> ExactObservedProvider {
        let mut providers = self
            .fiery_battle_will_windows
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id)
            .map(|key| key.provider_actor_id)
            .collect::<Vec<_>>();
        providers.sort_unstable();
        providers.dedup();
        match providers.as_slice() {
            [] => ExactObservedProvider::None,
            [provider_actor_id] => ExactObservedProvider::One(*provider_actor_id),
            _ => ExactObservedProvider::Ambiguous,
        }
    }

    fn observe_fiery_battle_will_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let before_provider = self.exact_fiery_battle_will_provider(target_actor_id);
        self.fiery_battle_will_pending_transitions
            .entry(target_actor_id)
            .or_insert(FieryBattleWillPendingTransition {
                before_provider,
                event_provider: ExactObservedProvider::None,
                saw_applied: false,
                invalid: false,
            });
        if let Some(wire) = self.current_wire {
            self.fiery_battle_will_transition_wires
                .insert(target_actor_id, wire);
        }

        let Some(raw_source_actor_id) = status.source.map(|source| source.actor_id.0) else {
            self.invalidate_fiery_battle_will_target(target_actor_id);
            return;
        };
        let provider_actor_id = self.resolve_owner_actor_id(raw_source_actor_id);
        let pending = self
            .fiery_battle_will_pending_transitions
            .get_mut(&target_actor_id)
            .expect("the current Fiery Battle Will wire was initialized above");
        pending.event_provider = match pending.event_provider {
            ExactObservedProvider::None => ExactObservedProvider::One(provider_actor_id),
            ExactObservedProvider::One(previous) if previous == provider_actor_id => {
                ExactObservedProvider::One(previous)
            }
            ExactObservedProvider::One(_) | ExactObservedProvider::Ambiguous => {
                ExactObservedProvider::Ambiguous
            }
        };
        let window = EffectWindowKey {
            target_actor_id,
            provider_actor_id,
            instance_id: status.instance_id.map(|instance| instance.0),
        };
        match status.state {
            StatusState::Applied => {
                if !pending.saw_applied {
                    // The child aura is a 1.1-second replacement snapshot.
                    // The first exact apply in a wire supersedes earlier
                    // instances; terminal rows for those older instances may
                    // follow later in the same wire.
                    self.fiery_battle_will_windows
                        .retain(|key| key.target_actor_id != target_actor_id);
                    pending.saw_applied = true;
                }
                self.fiery_battle_will_windows.insert(window);
            }
            StatusState::Removed => {
                if pending.saw_applied {
                    self.fiery_battle_will_windows.remove(&window);
                } else {
                    // A terminal-only wire ends this resolved provider's aura
                    // even when capture began after the short child instance
                    // was created and its exact instance was never retained.
                    self.fiery_battle_will_windows.retain(|key| {
                        key.target_actor_id != target_actor_id
                            || key.provider_actor_id != provider_actor_id
                    });
                }
            }
            StatusState::Refreshed | StatusState::Stacked | StatusState::Consumed => {
                self.invalidate_fiery_battle_will_target(target_actor_id);
            }
        }
    }

    fn invalidate_fiery_battle_will_target(&mut self, target_actor_id: u64) {
        self.fiery_battle_will_windows
            .retain(|key| key.target_actor_id != target_actor_id);
        self.fiery_battle_will_attack_witnesses
            .retain(|key| key.target_actor_id != target_actor_id);
        if let Some(pending) = self
            .fiery_battle_will_pending_transitions
            .get_mut(&target_actor_id)
        {
            pending.invalid = true;
        }
        if let Some(wire) = self.current_wire {
            self.fiery_battle_will_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn reconcile_fiery_battle_will_staged_states(&mut self) {
        let pending = std::mem::take(&mut self.fiery_battle_will_pending_transitions);
        for (target_actor_id, transition) in pending {
            if transition.invalid {
                continue;
            }
            let after_provider = self.exact_fiery_battle_will_provider(target_actor_id);
            let exact_event_provider = match transition.event_provider {
                ExactObservedProvider::One(provider_actor_id) => provider_actor_id,
                ExactObservedProvider::None | ExactObservedProvider::Ambiguous => {
                    self.invalidate_fiery_battle_will_target(target_actor_id);
                    continue;
                }
            };
            let has_status_confounder = self.formula_status_semantically_changed_on_wire(
                target_actor_id,
                self.runtime.fiery_battle_will.effect_id,
            );
            let has_unresolved_confounder = self
                .unresolved_status_windows
                .iter()
                .any(|key| key.target_actor_id == target_actor_id);
            if has_status_confounder || has_unresolved_confounder {
                self.invalidate_fiery_battle_will_target(target_actor_id);
                continue;
            }
            match (transition.before_provider, after_provider) {
                (ExactObservedProvider::None, ExactObservedProvider::One(provider_actor_id)) => {
                    if exact_event_provider != provider_actor_id
                        || provider_actor_id == target_actor_id
                        || !self.active_players.contains(&provider_actor_id)
                        || !self.fiery_battle_will_mirrored_raw_percent_transition(
                            target_actor_id,
                            self.runtime.fiery_battle_will.provider_raw_percent_delta,
                        )
                    {
                        self.invalidate_fiery_battle_will_target(target_actor_id);
                        continue;
                    }
                    self.fiery_battle_will_attack_witnesses
                        .insert(ObservedAttackProviderKey {
                            target_actor_id,
                            provider_actor_id,
                        });
                }
                (
                    ExactObservedProvider::One(before_provider_actor_id),
                    ExactObservedProvider::One(after_provider_actor_id),
                ) if before_provider_actor_id == after_provider_actor_id => {
                    // The 1.1-second child aura rotates instance IDs. A remove
                    // plus apply from the same resolved player is a lifecycle
                    // refresh, not another +10% Attack application.
                    let key = ObservedAttackProviderKey {
                        target_actor_id,
                        provider_actor_id: after_provider_actor_id,
                    };
                    if exact_event_provider != after_provider_actor_id {
                        self.invalidate_fiery_battle_will_target(target_actor_id);
                    } else if !self.fiery_battle_will_attack_witnesses.contains(&key) {
                        // Capture may begin inside the short aura heartbeat,
                        // leaving an exact same-owner window without its
                        // onset. A later isolated mirrored +1000 packet
                        // transition is sufficient to establish the same
                        // narrow observed marginal; no residual is assigned.
                        if self.fiery_battle_will_mirrored_raw_percent_transition(
                            target_actor_id,
                            self.runtime.fiery_battle_will.provider_raw_percent_delta,
                        ) {
                            self.fiery_battle_will_attack_witnesses.insert(key);
                        } else {
                            self.invalidate_fiery_battle_will_target(target_actor_id);
                        }
                    }
                }
                (ExactObservedProvider::One(provider_actor_id), ExactObservedProvider::None) => {
                    let key = ObservedAttackProviderKey {
                        target_actor_id,
                        provider_actor_id,
                    };
                    if exact_event_provider != provider_actor_id
                        || !self.fiery_battle_will_attack_witnesses.remove(&key)
                        || !self.fiery_battle_will_mirrored_raw_percent_transition(
                            target_actor_id,
                            -self.runtime.fiery_battle_will.provider_raw_percent_delta,
                        )
                    {
                        self.invalidate_fiery_battle_will_target(target_actor_id);
                    }
                }
                _ => self.invalidate_fiery_battle_will_target(target_actor_id),
            }
        }
    }

    fn formula_status_semantically_changed_on_wire(
        &self,
        target_actor_id: u64,
        excluded_effect_id: i64,
    ) -> bool {
        let changed_effect_ids = self
            .formula_status_prior_values_current_wire
            .keys()
            .filter(|key| {
                key.target_actor_id == target_actor_id && key.effect_id != excluded_effect_id
            })
            .map(|key| key.effect_id)
            .collect::<HashSet<_>>();
        changed_effect_ids.into_iter().any(|effect_id| {
            let keys = self
                .formula_statuses
                .keys()
                .chain(self.formula_status_prior_values_current_wire.keys())
                .filter(|key| key.target_actor_id == target_actor_id && key.effect_id == effect_id)
                .copied()
                .collect::<HashSet<_>>();
            let mut before = BTreeMap::<FormulaStatusValue, u64>::new();
            let mut after = BTreeMap::<FormulaStatusValue, u64>::new();
            for key in keys {
                let after_value = self.formula_statuses.get(&key).copied();
                let before_value = self
                    .formula_status_prior_values_current_wire
                    .get(&key)
                    .copied()
                    .unwrap_or(after_value);
                if let Some(value) = before_value {
                    *before.entry(value).or_default() += 1;
                }
                if let Some(value) = after_value {
                    *after.entry(value).or_default() += 1;
                }
            }
            before != after
        })
    }

    fn fiery_battle_will_mirrored_raw_percent_transition(
        &self,
        target_actor_id: u64,
        expected_delta: i64,
    ) -> bool {
        let Some(previous) = self.states.get(&target_actor_id) else {
            return false;
        };
        let Some(current) = self.staged_states.get(&target_actor_id) else {
            return false;
        };
        [
            (&previous.physical_attack, &current.physical_attack),
            (&previous.magical_attack, &current.magical_attack),
        ]
        .into_iter()
        .all(|(before, after)| {
            before.raw_percent_packet_observed
                && after.raw_percent_packet_observed
                && before
                    .raw_percent
                    .zip(after.raw_percent)
                    .is_some_and(|(before, after)| {
                        after.checked_sub(before) == Some(expected_delta)
                    })
        })
    }

    fn observe_thunderwind_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
        observed_micros: u64,
    ) {
        let target_actor_id = status.target.actor_id.0;
        let instance_id = status.instance_id.map(|instance| instance.0);
        let provider_actor_id = status.source.map(|source| source.actor_id.0);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);

        if active {
            let Some(provider_actor_id) = provider_actor_id else {
                self.mark_thunderwind_transition(target_actor_id);
                return;
            };
            let exact_proxy = self.entity_type_by_actor.get(&provider_actor_id).copied()
                == i32::try_from(self.runtime.thunderwind.summon_entity_type_id).ok()
                && self.summon_config_by_actor.get(&provider_actor_id).copied()
                    == Some(self.runtime.thunderwind.summon_config_id)
                && self.actor_ancestry.has_direct_owner_evidence_at(
                    provider_actor_id,
                    observed_micros,
                    ActorOwnershipEvidence::ConfirmedEntityAttributes,
                );
            let source_level = status.level.map(i64::from);
            if !exact_proxy
                || source_level.is_none()
                || self.thunderwind_vector(source_level.unwrap()).is_none()
            {
                self.thunderwind_windows.retain(|key, _| {
                    key.target_actor_id != target_actor_id
                        || key.provider_actor_id != provider_actor_id
                        || (instance_id.is_some() && key.instance_id != instance_id)
                });
                self.clear_thunderwind_provider_state(target_actor_id);
                self.mark_thunderwind_transition(target_actor_id);
                return;
            }
            self.thunderwind_windows.insert(
                EffectWindowKey {
                    target_actor_id,
                    provider_actor_id,
                    instance_id,
                },
                ThunderwindWindow {
                    source_level: source_level.expect("validated above"),
                },
            );
        } else {
            self.thunderwind_windows.retain(|key, _| {
                if key.target_actor_id != target_actor_id {
                    return true;
                }
                if instance_id.is_some() && key.instance_id != instance_id {
                    return true;
                }
                if let Some(provider_actor_id) = provider_actor_id
                    && key.provider_actor_id != provider_actor_id
                {
                    return true;
                }
                false
            });
            self.clear_thunderwind_provider_state(target_actor_id);
        }
        self.mark_thunderwind_transition(target_actor_id);
    }

    fn observe_inspiration_recipient_dependency_status(
        &mut self,
        status: &rlogs_events::StatusEvent,
    ) {
        let target_entity_uuid = status.target.entity_uuid.0;
        if target_entity_uuid == 0 {
            return;
        }
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        let exact_recipient_status = status.source == Some(status.target)
            && status.level
                == Some(
                    self.runtime
                        .inspiration
                        .recipient_dependency
                        .required_status_level,
                )
            && status.stacks == Some(1);
        if active && exact_recipient_status {
            self.inspiration_recipient_dependency_entities
                .insert(target_entity_uuid);
        } else {
            self.inspiration_recipient_dependency_entities
                .remove(&target_entity_uuid);
        }
    }

    fn observe_thunderwind_child_status(&mut self, status: &rlogs_events::StatusEvent) {
        let target_actor_id = status.target.actor_id.0;
        let self_sourced = status.source.is_some_and(|source| source == status.target);
        let active = matches!(
            status.state,
            StatusState::Applied | StatusState::Refreshed | StatusState::Stacked
        ) || (status.state == StatusState::Consumed
            && status.stacks.unwrap_or_default() > 0);
        if active && self_sourced {
            self.thunderwind_child_targets.insert(target_actor_id);
        } else {
            self.thunderwind_child_targets.remove(&target_actor_id);
            self.clear_thunderwind_provider_state(target_actor_id);
        }
        self.mark_thunderwind_transition(target_actor_id);
    }

    fn mark_thunderwind_transition(&mut self, target_actor_id: u64) {
        if let Some(wire) = self.current_wire {
            self.thunderwind_transition_wires
                .insert(target_actor_id, wire);
        }
    }

    fn clear_thunderwind_provider_state(&mut self, target_actor_id: u64) {
        if let Some(state) = self.states.get_mut(&target_actor_id) {
            state.thunderwind_providers.clear();
        }
        if let Some(state) = self.staged_states.get_mut(&target_actor_id) {
            state.thunderwind_providers.clear();
        }
    }

    fn thunderwind_vector(&self, source_level: i64) -> Option<ThunderwindVectorRuntimeConfig> {
        self.runtime
            .thunderwind
            .packet_proven_vectors
            .iter()
            .copied()
            .find(|vector| vector.source_level == source_level)
    }

    fn observe_attributes(
        &mut self,
        actor_id: u64,
        entity_uuid: i64,
        update_kind: EntityAttributeUpdateKind,
        ownership: Option<&rlogs_events::ActorOwnershipUpdate>,
        attributes: &[EntityAttribute],
        observed_micros: u64,
    ) {
        self.actor_ancestry.observe_entity(EntityRef {
            actor_id: rlogs_events::ActorId(actor_id),
            entity_uuid: rlogs_events::EntityUuid(entity_uuid),
        });
        if entity_uuid != 0 {
            if let Some(previous_entity_uuid) = self
                .attribute_state_entity_uuid_by_actor
                .insert(actor_id, entity_uuid)
            {
                if previous_entity_uuid != entity_uuid
                    && self
                        .attribute_state_actor_by_entity_uuid
                        .get(&previous_entity_uuid)
                        == Some(&actor_id)
                {
                    self.attribute_state_actor_by_entity_uuid
                        .remove(&previous_entity_uuid);
                }
            }
            self.attribute_state_actor_by_entity_uuid
                .insert(entity_uuid, actor_id);
        }
        self.observe_canonical_ownership(actor_id, entity_uuid, ownership, observed_micros);
        let mut formula_attributes = if update_kind == EntityAttributeUpdateKind::Snapshot {
            BTreeMap::new()
        } else {
            self.formula_attributes_by_actor
                .get(&actor_id)
                .cloned()
                .unwrap_or_default()
        };
        for attribute in attributes {
            if let Some(value) = integer_attribute(attribute) {
                formula_attributes.insert(attribute.attribute_id, value);
            }
        }
        self.formula_attributes_by_actor
            .insert(actor_id, formula_attributes);
        self.observe_thunderwind_proxy_attributes(actor_id, attributes);
        if update_kind == EntityAttributeUpdateKind::Snapshot {
            self.inspiration_snapshot_targets.insert(actor_id);
            self.fatal_spiral_snapshot_targets.insert(actor_id);
        }
        let rule = state_rdps_observation_rule()
            .expect("catalog was validated when the projector was built");
        let previous_state = self
            .staged_states
            .get(&actor_id)
            .cloned()
            .or_else(|| self.states.get(&actor_id).cloned())
            .unwrap_or_default();
        let snapshot_has_critical_damage = attributes.iter().any(|attribute| {
            attribute.attribute_id == self.runtime.team_luck.critical_damage_attribute_id
        });
        let snapshot_has_lucky_damage = attributes.iter().any(|attribute| {
            attribute.attribute_id == self.runtime.team_luck.lucky_damage_attribute_id
        });
        let mut next = if update_kind == EntityAttributeUpdateKind::Snapshot {
            // A snapshot is authoritative. Carrying omitted values forward
            // would combine two different character states and can silently
            // manufacture rDPS. Provider decomposition is deliberately reset
            // until a later packet transition proves it again.
            ActorHpState::default()
        } else {
            previous_state.clone()
        };
        let previous_percent = next.raw_percent;
        let previous_physical_attack_percent = next.physical_attack.raw_percent;
        let previous_magical_attack_percent = next.magical_attack.raw_percent;
        let previous_harmony_primary = next.harmony_primary_by_class.clone();
        let previous_mechanical_primary = next.mechanical_primary_by_class.clone();
        let mechanical_actor_class_id = self
            .recipient_class_id_for_actor(actor_id, &self.runtime.mechanical_power.recipient_rules);
        for attribute in attributes {
            let Some(value) = integer_attribute(attribute) else {
                continue;
            };
            if let Some(property) = property_for_damage_final_attribute_id(attribute.attribute_id) {
                next.element_damage_by_property.insert(property, value);
            }
            for recipient_rule in &self.runtime.mechanical_power.recipient_rules {
                update_attack_family_attribute(
                    next.mechanical_primary_by_class
                        .entry(recipient_rule.recipient_class_id)
                        .or_default(),
                    recipient_rule.primary_attribute_family,
                    attribute.attribute_id,
                    value,
                );
            }
            for recipient_rule in &self.runtime.harmony_grace.recipient_rules {
                update_attack_family_attribute(
                    next.harmony_primary_by_class
                        .entry(recipient_rule.recipient_class_id)
                        .or_default(),
                    recipient_rule.primary_attribute_family,
                    attribute.attribute_id,
                    value,
                );
            }
            if let Some(index) = self
                .runtime
                .inspiration
                .primary_raw_add_attribute_ids
                .iter()
                .position(|attribute_id| *attribute_id == attribute.attribute_id)
            {
                next.primary_raw_add[index] = Some(value);
            }
            if attribute.attribute_id == ATTR_CURRENT_HP {
                next.current_value = Some(value);
            } else if rule.is_some_and(|rule| attribute.attribute_id == rule.base_attribute_id) {
                next.base_value = Some(value);
            } else if rule.is_some_and(|rule| attribute.attribute_id == rule.final_attribute_id) {
                next.final_value = Some(value);
            } else if attribute.attribute_id == ATTR_MAX_HP_EXTRA_ADD {
                next.extra_add = Some(value);
            } else if rule
                .is_some_and(|rule| attribute.attribute_id == rule.percentage_attribute_id)
            {
                next.raw_percent = Some(value);
            } else if rule
                .is_some_and(|rule| attribute.attribute_id == rule.intermediate_attribute_id)
            {
                next.intermediate_value = Some(value);
            } else if rule
                .is_some_and(|rule| attribute.attribute_id == rule.extra_percentage_attribute_id)
            {
                next.raw_extra_percent = Some(value);
            } else if attribute.attribute_id == self.runtime.team_luck.critical_damage_attribute_id
            {
                next.critical_damage_raw = Some(value);
            } else if attribute.attribute_id == self.runtime.team_luck.lucky_damage_attribute_id {
                next.lucky_damage_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.enhanced_synergy.physical_boost_attribute_id
            {
                next.physical_boost_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.enhanced_synergy.magical_boost_attribute_id
            {
                next.magical_boost_raw = Some(value);
            } else if attribute.attribute_id == self.runtime.blessing.general_damage_attribute_id {
                next.general_damage_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.thunderwind.critical_chance_attribute_id
            {
                next.critical_chance_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.thunderwind.critical_damage_attribute_id
            {
                next.critical_damage_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.attack_families.physical.final_attribute_id
            {
                next.physical_attack.final_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .attack_families
                    .physical
                    .intermediate_attribute_id
            {
                next.physical_attack.intermediate_value = Some(value);
            } else if attribute.attribute_id
                == self.runtime.attack_families.physical.base_add_attribute_id
            {
                next.physical_attack.base_add = Some(value);
            } else if attribute.attribute_id
                == self.runtime.attack_families.physical.extra_add_attribute_id
            {
                next.physical_attack.extra_add = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .attack_families
                    .physical
                    .raw_percent_attribute_id
            {
                next.physical_attack.raw_percent = Some(value);
                next.physical_attack.raw_percent_packet_observed = true;
            } else if attribute.attribute_id
                == self.runtime.attack_families.magical.final_attribute_id
            {
                next.magical_attack.final_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .attack_families
                    .magical
                    .intermediate_attribute_id
            {
                next.magical_attack.intermediate_value = Some(value);
            } else if attribute.attribute_id
                == self.runtime.attack_families.magical.base_add_attribute_id
            {
                next.magical_attack.base_add = Some(value);
            } else if attribute.attribute_id
                == self.runtime.attack_families.magical.extra_add_attribute_id
            {
                next.magical_attack.extra_add = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .attack_families
                    .magical
                    .raw_percent_attribute_id
            {
                next.magical_attack.raw_percent = Some(value);
                next.magical_attack.raw_percent_packet_observed = true;
            } else if attribute.attribute_id
                == self.runtime.inspiration.critical_chance_attribute_id
            {
                next.critical_chance_raw = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .inspiration
                    .critical_chance_raw_add_attribute_id
            {
                next.critical_chance_raw_add = Some(value);
            } else if attribute.attribute_id == self.runtime.inspiration.lucky_chance_attribute_id {
                next.lucky_chance_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.inspiration.lucky_chance_raw_add_attribute_id
            {
                next.lucky_chance_raw_add = Some(value);
            } else if attribute.attribute_id == self.runtime.inspiration.mastery_attribute_id {
                next.mastery_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.inspiration.mastery_raw_add_attribute_id
            {
                next.mastery_raw_add = Some(value);
            } else if attribute.attribute_id == self.runtime.inspiration.versatility_attribute_id {
                next.versatility_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.inspiration.versatility_raw_add_attribute_id
            {
                next.versatility_raw_add = Some(value);
            } else if attribute.attribute_id
                == self.runtime.inspiration.external_damage_attribute_id
            {
                next.external_damage_raw = Some(value);
            } else if attribute.attribute_id
                == self.runtime.inspiration.property_damage_attribute_id
            {
                next.property_damage_raw = Some(value);
            } else if attribute.attribute_id == self.runtime.inspiration.haste_attribute_id {
                next.haste_percent_basis_points = Some(value);
            } else if attribute.attribute_id == self.runtime.inspire.normal_speed_attribute_id {
                next.normal_action_speed_basis_points = Some(value);
            } else if attribute.attribute_id == self.runtime.inspire.guide_speed_attribute_id {
                next.guide_action_speed_basis_points = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .current_attribute_id
            {
                next.all_element.current_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .total_attribute_id
            {
                next.all_element.total_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .add_attribute_id
            {
                next.all_element.add_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .extra_add_attribute_id
            {
                next.all_element.extra_add_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .percent_attribute_id
            {
                next.all_element.percent_value = Some(value);
            } else if attribute.attribute_id
                == self
                    .runtime
                    .highland_blood
                    .all_element_family
                    .extra_percent_attribute_id
            {
                next.all_element.extra_percent_value = Some(value);
            }
        }

        if next.critical_damage_raw.is_some() {
            self.team_luck_critical_ever_observed.insert(actor_id);
            self.team_luck_critical_cleared_by_snapshot
                .remove(&actor_id);
        } else if update_kind == EntityAttributeUpdateKind::Snapshot
            && !snapshot_has_critical_damage
            && self.team_luck_critical_ever_observed.contains(&actor_id)
        {
            self.team_luck_critical_cleared_by_snapshot.insert(actor_id);
        }
        if next.lucky_damage_raw.is_some() {
            self.team_luck_lucky_ever_observed.insert(actor_id);
            self.team_luck_lucky_cleared_by_snapshot.remove(&actor_id);
        } else if update_kind == EntityAttributeUpdateKind::Snapshot
            && !snapshot_has_lucky_damage
            && self.team_luck_lucky_ever_observed.contains(&actor_id)
        {
            self.team_luck_lucky_cleared_by_snapshot.insert(actor_id);
        }

        if let Some(rule) = rule
            && let (Some(previous), Some(current)) = (previous_percent, next.raw_percent)
            && previous != current
        {
            let desired =
                self.desired_provider_percentages(rule, actor_id, entity_uuid, observed_micros);
            let current_total = next.provider_raw_percent.values().copied().sum::<i64>();
            let desired_total = desired.values().copied().sum::<i64>();
            if desired_total.checked_sub(current_total) == current.checked_sub(previous) {
                next.provider_raw_percent = desired;
            } else {
                // The attribute changed, but the packet-observed provider
                // windows do not explain it exactly. Keep every event and stop
                // attribution until a later exact transition re-establishes
                // the provider decomposition.
                next.provider_raw_percent.clear();
            }
        }
        let desired_functional_amp = self
            .desired_functional_amp_provider_percentages(actor_id, entity_uuid)
            .into_iter()
            .filter_map(|((provider_actor_id, provider_entity_uuid), value)| {
                (self.actor_ancestry.actor_for_entity(provider_entity_uuid)
                    == Some(provider_actor_id))
                .then_some((provider_actor_id, value))
            })
            .collect::<BTreeMap<_, _>>();
        complete_exact_raw_percent(&mut next.physical_attack);
        complete_exact_raw_percent(&mut next.magical_attack);
        complete_exact_extra_add(&mut next.physical_attack);
        complete_exact_extra_add(&mut next.magical_attack);
        for family in next.harmony_primary_by_class.values_mut() {
            complete_exact_raw_percent(family);
            complete_exact_extra_add(family);
        }
        for family in next.mechanical_primary_by_class.values_mut() {
            complete_exact_raw_percent(family);
            complete_exact_extra_add(family);
        }
        reconcile_external_percent_family(
            previous_physical_attack_percent,
            &mut next.physical_attack,
            &desired_functional_amp,
        );
        reconcile_external_percent_family(
            previous_magical_attack_percent,
            &mut next.magical_attack,
            &desired_functional_amp,
        );
        let mut harmony_transition_candidates = Vec::new();
        for recipient_rule in &self.runtime.harmony_grace.recipient_rules {
            // Harmony Grace is universal: the status applies every listed
            // primary-stat increase to every recipient. The rule's class id
            // identifies only the downstream damage-conversion route; it is
            // not an application condition for this provider decomposition.
            let desired = self.desired_harmony_grace_provider_percentages(actor_id, recipient_rule);
            let family = next
                .harmony_primary_by_class
                .entry(recipient_rule.recipient_class_id)
                .or_default();
            let previous = previous_harmony_primary
                .get(&recipient_rule.recipient_class_id)
                .cloned()
                .unwrap_or_default();
            reconcile_external_percent_family(previous.raw_percent, family, &desired);
            reconcile_external_percent_family_from_exact_prior(&previous, family, &desired);
            harmony_transition_candidates.push((previous, family.clone(), desired));
        }
        for (previous, current, desired) in harmony_transition_candidates {
            self.record_harmony_grace_primary_transition_witness(
                actor_id, &previous, &current, &desired,
            );
        }
        let mut mechanical_transition_candidates = Vec::new();
        for recipient_rule in &self.runtime.mechanical_power.recipient_rules {
            let desired = if mechanical_actor_class_id == Some(recipient_rule.recipient_class_id) {
                self.desired_mechanical_power_provider_percentages(actor_id, recipient_rule)
            } else {
                BTreeMap::new()
            };
            let family = next
                .mechanical_primary_by_class
                .entry(recipient_rule.recipient_class_id)
                .or_default();
            let previous = previous_mechanical_primary
                .get(&recipient_rule.recipient_class_id)
                .cloned()
                .unwrap_or_default();
            reconcile_external_percent_family(previous.raw_percent, family, &desired);
            reconcile_external_percent_family_from_exact_prior(&previous, family, &desired);
            mechanical_transition_candidates.push((previous, family.clone(), desired));
        }
        for (previous, current, desired) in mechanical_transition_candidates {
            self.record_mechanical_power_primary_transition_witness(
                actor_id, &previous, &current, &desired,
            );
        }
        self.staged_states.insert(actor_id, next);
    }

    fn recipient_class_id_for_actor(
        &self,
        actor_id: u64,
        recipient_rules: &[PrimaryStatRecipientRule],
    ) -> Option<i32> {
        self.class_id_by_actor
            .get(&actor_id)
            .copied()
            .or_else(|| {
                let observed_abilities = self.observed_ability_ids_by_actor.get(&actor_id)?;
                specialization_identity_from_observed_abilities(observed_abilities.iter().copied())
                    .ok()
                    .flatten()
                    .map(|(class_id, _)| class_id)
            })
            .or_else(|| {
                // A build-specific runtime with exactly one recipient rule has
                // already constrained the legal route. This preserves the
                // sealed legacy proof when its attribute snapshot precedes
                // actor identity, without guessing on current multi-class
                // builds.
                (recipient_rules.len() == 1).then_some(recipient_rules[0].recipient_class_id)
            })
    }

    fn recipient_class_and_specialization_for_actor(&self, actor_id: u64) -> Option<(i32, i32)> {
        let direct_class_id = self.class_id_by_actor.get(&actor_id).copied();
        let direct_specialization_id = self.specialization_id_by_actor.get(&actor_id).copied();
        let observed_identity =
            self.observed_ability_ids_by_actor
                .get(&actor_id)
                .and_then(|ability_ids| {
                    specialization_identity_from_observed_abilities(ability_ids.iter().copied())
                        .ok()
                        .flatten()
                });
        match (direct_class_id, direct_specialization_id, observed_identity) {
            (Some(class_id), Some(specialization_id), Some(observed))
                if observed != (class_id, specialization_id) =>
            {
                None
            }
            (Some(class_id), Some(specialization_id), _) => Some((class_id, specialization_id)),
            (
                class_id,
                specialization_id,
                Some((observed_class_id, observed_specialization_id)),
            ) if class_id.is_none_or(|class_id| class_id == observed_class_id)
                && specialization_id.is_none_or(|specialization_id| {
                    specialization_id == observed_specialization_id
                }) =>
            {
                Some((observed_class_id, observed_specialization_id))
            }
            _ => None,
        }
    }

    fn observe_thunderwind_proxy_attributes(
        &mut self,
        actor_id: u64,
        attributes: &[EntityAttribute],
    ) {
        if self.entity_type_by_actor.get(&actor_id).copied()
            != i32::try_from(self.runtime.thunderwind.summon_entity_type_id).ok()
        {
            return;
        }
        let config = attributes
            .iter()
            .find(|attribute| {
                attribute.attribute_id == self.runtime.thunderwind.summon_config_attribute_id
            })
            .and_then(integer_attribute);
        if let Some(config) = config {
            if config == self.runtime.thunderwind.summon_config_id {
                self.summon_config_by_actor.insert(actor_id, config);
            } else {
                self.summon_config_by_actor.remove(&actor_id);
            }
        }
    }

    fn observe_canonical_ownership(
        &mut self,
        actor_id: u64,
        direct_entity_uuid: i64,
        ownership: Option<&rlogs_events::ActorOwnershipUpdate>,
        observed_micros: u64,
    ) {
        match ownership {
            Some(rlogs_events::ActorOwnershipUpdate::Confirmed { owner_entity_uuid }) => {
                self.actor_ancestry.observe_owner_entity(
                    observed_micros,
                    EntityRef {
                        actor_id: rlogs_events::ActorId(actor_id),
                        entity_uuid: rlogs_events::EntityUuid(direct_entity_uuid),
                    },
                    owner_entity_uuid.0,
                    ActorOwnershipEvidence::ConfirmedEntityAttributes,
                );
            }
            Some(rlogs_events::ActorOwnershipUpdate::Cleared) => {
                self.actor_ancestry.clear_owner(
                    observed_micros,
                    EntityRef {
                        actor_id: rlogs_events::ActorId(actor_id),
                        entity_uuid: rlogs_events::EntityUuid(direct_entity_uuid),
                    },
                );
            }
            None => {}
        }
    }

    fn desired_provider_percentages(
        &self,
        rule: &StateRdpsRule,
        target_actor_id: u64,
        target_entity_uuid: i64,
        observed_micros: u64,
    ) -> BTreeMap<u64, i64> {
        let mut desired = BTreeMap::<u64, i64>::new();
        for (key, window) in &self.effect_windows {
            if key.target_actor_id != target_actor_id
                || window.target_entity_uuid != target_entity_uuid
                || window.desired_stacks == 0
                || observed_micros > window.expires_at_observed_micros
                || self.actor_ancestry.entity_for_actor(key.provider_actor_id)
                    != Some(window.provider_entity_uuid)
            {
                continue;
            }
            let raw = i64::from(window.desired_stacks).saturating_mul(rule.raw_percent_per_stack);
            desired
                .entry(key.provider_actor_id)
                .and_modify(|value| *value = (*value).max(raw))
                .or_insert(raw);
        }
        desired
    }

    fn desired_functional_amp_provider_percentages(
        &self,
        target_actor_id: u64,
        target_entity_uuid: i64,
    ) -> BTreeMap<(u64, i64), i64> {
        self.functional_amp_windows
            .iter()
            .filter(|key| {
                key.target_actor_id == target_actor_id
                    && key.target_entity_uuid == target_entity_uuid
            })
            .fold(BTreeMap::new(), |mut desired, key| {
                desired
                    .entry((key.provider_actor_id, key.provider_entity_uuid))
                    .and_modify(|value| {
                        *value = (*value).max(self.runtime.functional_amp.attack_percent_raw_delta)
                    })
                    .or_insert(self.runtime.functional_amp.attack_percent_raw_delta);
                desired
            })
    }

    fn desired_harmony_grace_provider_percentages(
        &self,
        target_actor_id: u64,
        recipient_rule: &PrimaryStatRecipientRule,
    ) -> BTreeMap<u64, i64> {
        self.harmony_grace_windows
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id)
            .fold(BTreeMap::new(), |mut desired, key| {
                desired
                    .entry(key.provider_actor_id)
                    .and_modify(|value| {
                        *value = (*value).max(recipient_rule.primary_percent_raw_delta)
                    })
                    .or_insert(recipient_rule.primary_percent_raw_delta);
                desired
            })
    }

    fn record_harmony_grace_primary_transition_witness(
        &mut self,
        target_actor_id: u64,
        previous: &AttackFamilyState,
        current: &AttackFamilyState,
        desired: &BTreeMap<u64, i64>,
    ) {
        let Some((provider_actor_id, witness)) =
            exact_primary_stat_transition_witness(self.current_wire, previous, current, desired)
        else {
            return;
        };
        let mut matching = self.harmony_grace_windows.iter().copied().filter(|key| {
            key.target_actor_id == target_actor_id && key.provider_actor_id == provider_actor_id
        });
        let Some(window) = matching.next() else {
            return;
        };
        if matching.next().is_some() {
            // Same-provider overlapping instances have unresolved stacking and
            // removal arbitration. Do not attach one transition to either.
            return;
        }
        self.harmony_grace_primary_transition_witnesses
            .entry(window)
            .or_default()
            .insert(PrimaryStatTransitionWitness {
                instance_id: window.instance_id,
                ..witness
            });
    }

    fn harmony_grace_primary_transition_witness(
        &self,
        recipient_actor_id: u64,
        provider_actor_id: u64,
        primary: &AttackFamilyState,
        provider_raw_percent: i64,
    ) -> Result<PrimaryStatTransitionWitness, &'static str> {
        let mut matching = self.harmony_grace_windows.iter().copied().filter(|key| {
            key.target_actor_id == recipient_actor_id && key.provider_actor_id == provider_actor_id
        });
        let window = matching.next().ok_or("provider_lifecycle_missing")?;
        if matching.next().is_some() {
            return Err("provider_lifecycle_ambiguous");
        }
        let base_add = primary.base_add.ok_or("primary_family_incomplete")?;
        let raw_percent = primary.raw_percent.ok_or("primary_family_incomplete")?;
        self.harmony_grace_primary_transition_witnesses
            .get(&window)
            .and_then(|witnesses| {
                witnesses.iter().copied().find(|witness| {
                    witness.base_add == base_add
                        && witness.active_raw_percent == raw_percent
                        && witness.provider_raw_percent == provider_raw_percent
                })
            })
            .ok_or("primary_transition_witness_missing")
    }

    fn desired_mechanical_power_provider_percentages(
        &self,
        target_actor_id: u64,
        recipient_rule: &PrimaryStatRecipientRule,
    ) -> BTreeMap<u64, i64> {
        let primary_percent_raw_delta = self
            .mechanical_power_candidate_primary_percent_override
            .or_else(|| {
                self.runtime
                    .mechanical_power
                    .production_primary_percent_raw_delta(recipient_rule.recipient_class_id)
            })
            .unwrap_or(recipient_rule.primary_percent_raw_delta);
        self.mechanical_power_windows
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id)
            .fold(BTreeMap::new(), |mut desired, key| {
                desired
                    .entry(key.provider_actor_id)
                    .and_modify(|value| *value = (*value).max(primary_percent_raw_delta))
                    .or_insert(primary_percent_raw_delta);
                desired
            })
    }

    fn mechanical_power_exact_scoped_rebase_allowed(&self, provider_raw_percent: i64) -> bool {
        self.mechanical_power_candidate_primary_percent_override
            .is_some_and(|candidate| candidate == provider_raw_percent)
            || (self.runtime.mechanical_power.runtime_transfer_enabled
                && self
                    .runtime
                    .mechanical_power
                    .runtime_primary_percent_raw_deltas
                    .contains(&provider_raw_percent))
    }

    fn record_mechanical_power_primary_transition_witness(
        &mut self,
        target_actor_id: u64,
        previous: &AttackFamilyState,
        current: &AttackFamilyState,
        desired: &BTreeMap<u64, i64>,
    ) {
        let Some((provider_actor_id, witness)) =
            exact_primary_stat_transition_witness(self.current_wire, previous, current, desired)
        else {
            return;
        };
        let mut matching = self.mechanical_power_windows.iter().copied().filter(|key| {
            key.target_actor_id == target_actor_id && key.provider_actor_id == provider_actor_id
        });
        let Some(window) = matching.next() else {
            return;
        };
        if matching.next().is_some() {
            // Same-provider overlapping instances have unresolved stacking and
            // removal arbitration. Do not attach one transition to either.
            return;
        }
        self.mechanical_power_primary_transition_witnesses
            .entry(window)
            .or_default()
            .insert(PrimaryStatTransitionWitness {
                instance_id: window.instance_id,
                ..witness
            });
    }

    fn mechanical_power_primary_transition_witness(
        &self,
        recipient_actor_id: u64,
        provider_actor_id: u64,
        primary: &AttackFamilyState,
        provider_raw_percent: i64,
    ) -> Result<PrimaryStatTransitionWitness, &'static str> {
        let mut matching = self.mechanical_power_windows.iter().copied().filter(|key| {
            key.target_actor_id == recipient_actor_id && key.provider_actor_id == provider_actor_id
        });
        let window = matching.next().ok_or("provider_lifecycle_missing")?;
        if matching.next().is_some() {
            return Err("provider_lifecycle_ambiguous");
        }
        let base_add = primary.base_add.ok_or("primary_family_incomplete")?;
        let raw_percent = primary.raw_percent.ok_or("primary_family_incomplete")?;
        let exact_scoped_rebase_allowed =
            self.mechanical_power_exact_scoped_rebase_allowed(provider_raw_percent);
        let witness = self
            .mechanical_power_primary_transition_witnesses
            .get(&window)
            .and_then(|witnesses| {
                witnesses.iter().copied().find(|witness| {
                    witness.provider_raw_percent == provider_raw_percent
                        && (exact_scoped_rebase_allowed
                            || (witness.base_add == base_add
                                && witness.active_raw_percent == raw_percent))
                })
            })
            .ok_or("primary_transition_witness_missing")?;
        if exact_scoped_rebase_allowed {
            rebase_primary_stat_transition_witness(primary, witness)
                .ok_or("primary_transition_rebase_unproven")
        } else {
            Ok(witness)
        }
    }

    fn desired_inspiration_provider_modes(
        &self,
        target_actor_id: u64,
    ) -> Option<BTreeMap<u64, bool>> {
        let mut desired = BTreeMap::new();
        for (key, window) in &self.inspiration_windows {
            if key.target_actor_id != target_actor_id {
                continue;
            }
            if window
                .expires_at_observed_micros
                .is_none_or(|expires_at| self.latest_observed_micros > expires_at)
            {
                continue;
            }
            if let Some(existing) =
                desired.insert(key.provider_actor_id, window.provider_full_bloom)
                && existing != window.provider_full_bloom
            {
                // Two active instances disagree about the provider snapshot.
                // Retain both lifecycles but do not manufacture one magnitude.
                return None;
            }
        }
        Some(desired)
    }

    fn reconcile_inspiration_staged_states(&mut self) {
        let actor_ids = self.staged_states.keys().copied().collect::<Vec<_>>();
        for actor_id in actor_ids {
            let desired = self.desired_inspiration_provider_modes(actor_id);
            let previous = self.states.get(&actor_id).cloned();
            let Some(next) = self.staged_states.get_mut(&actor_id) else {
                continue;
            };
            if self.inspiration_snapshot_targets.contains(&actor_id) {
                next.inspiration_providers.clear();
                continue;
            }
            let Some(desired) = desired else {
                next.inspiration_providers.clear();
                continue;
            };
            reconcile_inspiration_state(
                previous.as_ref(),
                next,
                &desired,
                &self.runtime.inspiration.packet_proven_vectors,
                self.inspiration_candidate_audit_enabled,
            );
        }
    }

    fn reconcile_attribute_transfer_staged_states(&mut self) {
        let actor_ids = self.staged_states.keys().copied().collect::<Vec<_>>();
        for actor_id in actor_ids {
            if self.inspiration_snapshot_targets.contains(&actor_id) {
                continue;
            }
            let Some(previous) = self.states.get(&actor_id) else {
                continue;
            };
            let Some(next) = self.staged_states.get(&actor_id) else {
                continue;
            };
            let mut unbound = self
                .attribute_transfer_windows
                .iter()
                .filter(|(key, window)| key.target_actor_id == actor_id && window.lane.is_none())
                .map(|(key, _)| *key);
            let Some(key) = unbound.next() else {
                continue;
            };
            if unbound.next().is_some() {
                // One packet transition cannot identify two same-ID children.
                continue;
            }
            let Some(lane) = attribute_transfer_lane_transition(
                previous,
                next,
                self.runtime.attribute_transfer.substat_raw_delta,
                self.runtime
                    .attribute_transfer
                    .versatility_to_external_damage_numerator,
                self.runtime
                    .attribute_transfer
                    .versatility_to_external_damage_denominator,
            ) else {
                continue;
            };
            if let Some(window) = self.attribute_transfer_windows.get_mut(&key) {
                window.lane = Some(lane);
            }
        }
    }

    fn reconcile_thunderwind_staged_states(&mut self) {
        let actor_ids = self.staged_states.keys().copied().collect::<Vec<_>>();
        for actor_id in actor_ids {
            let desired = self.desired_thunderwind_provider(actor_id);
            let previous = self.states.get(&actor_id).cloned();
            let Some(next) = self.staged_states.get_mut(&actor_id) else {
                continue;
            };
            let Some((provider_actor_id, vector)) = desired else {
                next.thunderwind_providers.clear();
                continue;
            };
            let Some(previous) = previous else {
                next.thunderwind_providers.clear();
                continue;
            };

            if previous.thunderwind_providers.len() == 1
                && previous.thunderwind_providers.get(&provider_actor_id)
                    == Some(&ThunderwindProviderState {
                        critical_chance_raw_delta: vector.critical_chance_raw_delta,
                        critical_damage_raw_delta: vector.critical_damage_raw_delta,
                    })
            {
                if option_delta(previous.critical_chance_raw, next.critical_chance_raw) == Some(0)
                    && option_delta(previous.critical_damage_raw, next.critical_damage_raw)
                        == Some(0)
                {
                    next.thunderwind_providers
                        .clone_from(&previous.thunderwind_providers);
                } else {
                    next.thunderwind_providers.clear();
                }
                continue;
            }

            next.thunderwind_providers.clear();
            if previous.thunderwind_providers.is_empty()
                && option_delta(previous.critical_chance_raw, next.critical_chance_raw)
                    == Some(vector.critical_chance_raw_delta)
                && option_delta(previous.critical_damage_raw, next.critical_damage_raw)
                    == Some(vector.critical_damage_raw_delta)
            {
                next.thunderwind_providers.insert(
                    provider_actor_id,
                    ThunderwindProviderState {
                        critical_chance_raw_delta: vector.critical_chance_raw_delta,
                        critical_damage_raw_delta: vector.critical_damage_raw_delta,
                    },
                );
            }
        }
    }

    fn reconcile_fatal_spiral_staged_states(&mut self) {
        let actor_ids = self.staged_states.keys().copied().collect::<Vec<_>>();
        for actor_id in actor_ids {
            let desired_provider = self.desired_fatal_spiral_provider(actor_id);
            let transitions = self
                .fatal_spiral_transitions
                .get(&actor_id)
                .into_iter()
                .flatten()
                .map(|transition| FixedPointFamilyTransition {
                    provider_actor_id: self.resolve_owner_actor_id(transition.provider_actor_id),
                    provider_entity_uuid: transition.provider_entity_uuid,
                    active: transition.active,
                })
                .collect::<Vec<_>>();
            let previous = self.states.get(&actor_id).cloned();
            let Some(staged) = self.staged_states.get(&actor_id).cloned() else {
                continue;
            };

            if self.fatal_spiral_snapshot_targets.contains(&actor_id) {
                if let Some(next) = self.staged_states.get_mut(&actor_id) {
                    next.all_element.provider_basis_points.clear();
                }
                continue;
            }

            let deltas = previous.as_ref().and_then(|previous| {
                fixed_point_family_component_deltas(&previous.all_element, &staged.all_element)
            });

            // The first local snapshot can arrive after the buff was applied,
            // so application has no baseline. Removal still supplies the full
            // inverse transition and therefore proves the provider magnitude.
            if let Some([current, total, add, extra_add, percent, extra_percent]) = deltas {
                let mut inactive = transitions
                    .iter()
                    .filter(|transition| !transition.active)
                    .filter(|transition| transition.provider_actor_id != actor_id)
                    .map(|transition| {
                        (
                            transition.provider_actor_id,
                            transition.provider_entity_uuid,
                        )
                    })
                    .collect::<Vec<_>>();
                inactive.sort_unstable();
                inactive.dedup();
                let has_active_transition = transitions.iter().any(|transition| transition.active);
                let removed_basis_points = current.checked_neg();
                if !has_active_transition
                    && inactive.len() == 1
                    && current == total
                    && total == add
                    && extra_add == 0
                    && percent == 0
                    && extra_percent == 0
                    && removed_basis_points.is_some_and(|value| {
                        self.runtime
                            .highland_blood
                            .packet_proven_raw_deltas
                            .contains(&value)
                    })
                {
                    let (_, provider_entity_uuid) = inactive[0];
                    self.learn_fatal_spiral_provider_basis_points(
                        provider_entity_uuid,
                        removed_basis_points.expect("checked above"),
                    );
                }
            }

            let mut provider_basis_points = BTreeMap::new();
            if let Some((provider_actor_id, provider_entity_uuid)) = desired_provider {
                let preserved = previous.as_ref().is_some_and(|previous| {
                    previous.all_element.provider_basis_points.len() == 1
                        && previous
                            .all_element
                            .provider_basis_points
                            .contains_key(&provider_actor_id)
                        && transitions.is_empty()
                        && deltas == Some([0; 6])
                });
                if preserved {
                    provider_basis_points.clone_from(
                        &previous
                            .as_ref()
                            .expect("preservation requires previous state")
                            .all_element
                            .provider_basis_points,
                    );
                } else if let Some([current, total, add, extra_add, percent, extra_percent]) =
                    deltas
                {
                    let active_transitions = transitions
                        .iter()
                        .filter(|transition| {
                            transition.active
                                && transition.provider_actor_id == provider_actor_id
                                && transition.provider_entity_uuid == provider_entity_uuid
                        })
                        .count();
                    let inactive_transitions = transitions
                        .iter()
                        .filter(|transition| !transition.active)
                        .count();
                    let exact_application = previous.as_ref().is_some_and(|previous| {
                        previous.all_element.provider_basis_points.is_empty()
                    }) && active_transitions == 1
                        && inactive_transitions == 0
                        && current == total
                        && total == add
                        && extra_add == 0
                        && percent == 0
                        && extra_percent == 0
                        && self
                            .runtime
                            .highland_blood
                            .packet_proven_raw_deltas
                            .contains(&current);
                    if exact_application {
                        self.learn_fatal_spiral_provider_basis_points(
                            provider_entity_uuid,
                            current,
                        );
                        provider_basis_points.insert(provider_actor_id, current);
                    }
                }

                if provider_basis_points.is_empty()
                    && !self
                        .fatal_spiral_ambiguous_provider_entities
                        .contains(&provider_entity_uuid)
                {
                    if let Some(&basis_points) = self
                        .fatal_spiral_provider_basis_points_by_entity_uuid
                        .get(&provider_entity_uuid)
                    {
                        provider_basis_points.insert(provider_actor_id, basis_points);
                    }
                }
            }

            if let Some(next) = self.staged_states.get_mut(&actor_id) {
                next.all_element.provider_basis_points = provider_basis_points;
            }
        }
    }

    fn desired_fatal_spiral_provider(&self, target_actor_id: u64) -> Option<(u64, i64)> {
        let mut providers = self
            .fatal_spiral_windows
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id)
            .map(|key| {
                (
                    self.resolve_owner_actor_id(key.provider_actor_id),
                    key.provider_entity_uuid,
                )
            })
            .filter(|(provider_actor_id, _)| *provider_actor_id != target_actor_id)
            .filter(|(provider_actor_id, _)| self.active_players.contains(provider_actor_id))
            .collect::<Vec<_>>();
        providers.sort_unstable();
        providers.dedup();
        (providers.len() == 1).then(|| providers[0])
    }

    fn observe_fatal_spiral_provider_loadout(&mut self, actor: &rlogs_events::ActorEvent) {
        let imagine_ability_id = self.runtime.highland_blood.provider_imagine_ability_id;
        let mut basis_points = actor
            .primary_loadout
            .iter()
            .filter(|slot| slot.ability_id == Some(imagine_ability_id))
            .filter_map(|slot| {
                let tier_index = usize::try_from(slot.tier?.checked_sub(1)?).ok()?;
                self.runtime
                    .highland_blood
                    .packet_proven_raw_deltas
                    .get(tier_index)
                    .copied()
            })
            .collect::<Vec<_>>();
        basis_points.sort_unstable();
        basis_points.dedup();
        let entity_uuid = actor.actor.entity_uuid.0;
        match basis_points.as_slice() {
            [] => {}
            [value] => {
                self.fatal_spiral_equipped_basis_points_by_entity_uuid
                    .insert(entity_uuid, *value);
                self.fatal_spiral_ambiguous_provider_entities
                    .remove(&entity_uuid);
                self.fatal_spiral_provider_basis_points_by_entity_uuid
                    .insert(entity_uuid, *value);
            }
            _ => {
                self.fatal_spiral_equipped_basis_points_by_entity_uuid
                    .remove(&entity_uuid);
                self.fatal_spiral_provider_basis_points_by_entity_uuid
                    .remove(&entity_uuid);
                self.fatal_spiral_ambiguous_provider_entities
                    .insert(entity_uuid);
            }
        }
    }

    fn observe_arcane_time_decree_provider_loadout(&mut self, actor: &rlogs_events::ActorEvent) {
        let config = &self.runtime.arcane_time_decree;
        let mut magnitudes = actor
            .primary_loadout
            .iter()
            .filter(|slot| slot.ability_id == Some(config.provider_imagine_ability_id))
            .filter(|slot| {
                slot.item_id
                    .is_none_or(|item_id| item_id == config.provider_imagine_item_id)
            })
            .filter_map(|slot| config.basis_points_for_tier(slot.tier?))
            .collect::<Vec<_>>();
        magnitudes.sort_unstable();
        magnitudes.dedup();
        let entity_uuid = actor.actor.entity_uuid.0;
        match magnitudes.as_slice() {
            [magnitude] if entity_uuid != 0 => {
                self.arcane_time_decree_basis_points_by_provider_entity
                    .insert(entity_uuid, *magnitude);
            }
            [] if actor.loadout_observation.primary
                == rlogs_events::ActorLoadoutEvidence::ExactSlots =>
            {
                self.arcane_time_decree_basis_points_by_provider_entity
                    .remove(&entity_uuid);
            }
            [] => {}
            _ => {
                self.arcane_time_decree_basis_points_by_provider_entity
                    .remove(&entity_uuid);
            }
        }
    }

