    fn coordinated_strike_decision(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Result<ExactRationalDamageContributionEvent, &'static str> {
        let config = &self.runtime.coordinated_strike;
        if !config.runtime_transfer_enabled {
            return Err("runtime_transfer_disabled");
        }
        if damage.amount <= 0 {
            return Err("non_positive_damage");
        }
        if self.damage_has_unresolved_status_confounder(damage) {
            return Err("unresolved_status_confounder");
        }
        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let target_matches = |target_actor_id: u64| {
            target_actor_id == recipient_actor_id
                || (recipient_entity_uuid != 0
                    && self
                        .attribute_state_entity_uuid_by_actor
                        .get(&target_actor_id)
                        == Some(&recipient_entity_uuid))
        };
        if self
            .formula_status_prior_values_current_wire
            .keys()
            .any(|key| key.effect_id == config.effect_id && target_matches(key.target_actor_id))
        {
            return Err("same_wire_transition");
        }

        let mut providers = BTreeMap::new();
        for (key, value) in self.formula_statuses.iter().filter(|(key, value)| {
            key.effect_id == config.effect_id
                && target_matches(key.target_actor_id)
                && value.level == i64::from(config.required_level)
                && value.stacks == i64::from(config.required_stacks)
        }) {
            let Some(window) = self.coordinated_strike_windows.get(key) else {
                continue;
            };
            if observed_micros <= window.opened_observed_micros
                || observed_micros >= window.expires_at_observed_micros
            {
                continue;
            }
            if key.source_actor_id == 0 {
                return Err("provider_missing");
            }
            let provider_entity_uuid = value.source_entity_uuid.unwrap_or_default();
            let provider_actor_id = (provider_entity_uuid != 0)
                .then(|| self.actor_ancestry.actor_for_entity(provider_entity_uuid))
                .flatten()
                .unwrap_or(key.source_actor_id);
            let provider_actor_id = self.resolve_owner_actor_id(provider_actor_id);
            if provider_actor_id == recipient_actor_id
                || (recipient_entity_uuid != 0 && provider_entity_uuid == recipient_entity_uuid)
            {
                return Err("provider_is_recipient");
            }
            if !self.active_players.contains(&provider_actor_id) {
                return Err("provider_inactive");
            }
            let identity = if provider_entity_uuid != 0 {
                (0_u8, i128::from(provider_entity_uuid))
            } else {
                (1_u8, i128::from(provider_actor_id))
            };
            providers.entry(identity).or_insert(provider_actor_id);
        }
        if providers.len() != 1 {
            return Err(if providers.is_empty() {
                "provider_window_missing"
            } else {
                "provider_window_ambiguous"
            });
        }
        let provider_actor_id = *providers.values().next().ok_or("provider_window_missing")?;
        let selected = select_damage_stage(
            damage.ability.ok_or("ability_missing")?.0,
            damage.hit_event_id,
            damage.damage_source,
            damage.packet.owner_stage,
            damage.packet.owner_level,
        )
        .ok_or("damage_stage_missing")?;
        let actor_state = self
            .states
            .get(&recipient_actor_id)
            .or_else(|| {
                (recipient_entity_uuid != 0)
                    .then(|| {
                        self.attribute_state_actor_by_entity_uuid
                            .get(&recipient_entity_uuid)
                            .and_then(|actor_id| self.states.get(actor_id))
                    })
                    .flatten()
            })
            .ok_or("recipient_state_missing")?;
        let family = match selected.offensive_stat {
            OffensiveStatKind::PhysicalAttack => &actor_state.physical_attack,
            OffensiveStatKind::MagicalAttack => &actor_state.magical_attack,
        };
        if !family.raw_percent_packet_observed {
            return Err("recipient_attack_not_packet_observed");
        }
        let current_attack = family.final_value.ok_or("attack_family_incomplete")?;
        if family.raw_percent.ok_or("attack_family_incomplete")? < config.attack_raw_percent_delta {
            return Err("attack_state_excludes_provider_delta");
        }
        let provider_attack_marginal = exact_signed_attack_raw_percent_provider_marginal(
            family,
            config.attack_raw_percent_delta,
        )
        .ok_or("attack_family_formula_mismatch")?;
        exact_observed_final_attack_stage_contribution(
            observed_micros,
            config.effect_id,
            DamageContributionScope::Component("coordinated-strike-observed-final-attack-percent"),
            provider_actor_id,
            recipient_actor_id,
            damage.amount,
            current_attack,
            provider_attack_marginal,
            selected,
        )
        .ok_or("damage_coefficient_counterfactual_unproven")
    }

    fn all_class_aura_decision(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Result<(ExactRationalDamageContributionEvent, i64), &'static str> {
        let config = &self.runtime.all_class_aura;
        if !config.runtime_transfer_enabled {
            return Err("runtime_transfer_disabled");
        }
        if damage.amount <= 0 {
            return Err("non_positive_damage");
        }
        if self.damage_has_unresolved_status_confounder(damage) {
            return Err("unresolved_status_confounder");
        }
        // A cohort mutation serialized earlier on this wire may be the result
        // of the same action. Its pre/post role tier cannot be guessed.
        if self
            .formula_status_prior_values_current_wire
            .keys()
            .any(|key| key.effect_id == config.effect_id)
        {
            return Err("same_wire_transition");
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let target_matches = |target_actor_id: u64| {
            target_actor_id == recipient_actor_id
                || (recipient_entity_uuid != 0
                    && self
                        .attribute_state_entity_uuid_by_actor
                        .get(&target_actor_id)
                        == Some(&recipient_entity_uuid))
        };
        let mut provider_ids = BTreeSet::new();
        let mut recipient_window_count = 0_usize;
        for (key, value) in self.formula_statuses.iter().filter(|(key, value)| {
            key.effect_id == config.effect_id
                && target_matches(key.target_actor_id)
                && value.level == i64::from(config.required_level)
                && value.stacks == i64::from(config.required_stacks)
        }) {
            let Some(window) = self.all_class_aura_windows.get(key) else {
                continue;
            };
            if observed_micros <= window.opened_observed_micros
                || observed_micros >= window.expires_at_observed_micros
            {
                continue;
            }
            recipient_window_count += 1;
            let provider_entity_uuid = value.source_entity_uuid.unwrap_or_default();
            let provider_actor_id = (provider_entity_uuid != 0)
                .then(|| self.actor_ancestry.actor_for_entity(provider_entity_uuid))
                .flatten()
                .unwrap_or(key.source_actor_id);
            provider_ids.insert(self.resolve_owner_actor_id(provider_actor_id));
        }
        if recipient_window_count != 1 || provider_ids.len() != 1 {
            return Err(if recipient_window_count == 0 || provider_ids.is_empty() {
                "provider_window_missing"
            } else {
                "provider_window_ambiguous"
            });
        }
        let provider_actor_id = *provider_ids
            .iter()
            .next()
            .ok_or("provider_window_missing")?;
        if provider_actor_id == recipient_actor_id {
            return Err("provider_is_recipient");
        }
        if !self.active_players.contains(&provider_actor_id) {
            return Err("provider_inactive");
        }

        let provider_class_id = *self
            .class_id_by_actor
            .get(&provider_actor_id)
            .ok_or("provider_role_missing")?;
        let provider_role = class_role(provider_class_id)
            .ok()
            .flatten()
            .ok_or("provider_role_missing")?;
        let mut roles = BTreeSet::from([provider_role]);
        let mut cohort_targets = BTreeSet::new();
        for (key, window) in &self.all_class_aura_windows {
            if key.effect_id != config.effect_id
                || observed_micros <= window.opened_observed_micros
                || observed_micros >= window.expires_at_observed_micros
            {
                continue;
            }
            let Some(value) = self.formula_statuses.get(key) else {
                return Err("cohort_status_missing");
            };
            if value.level != i64::from(config.required_level)
                || value.stacks != i64::from(config.required_stacks)
            {
                return Err("cohort_status_malformed");
            }
            let source_entity_uuid = value.source_entity_uuid.unwrap_or_default();
            let cohort_provider = (source_entity_uuid != 0)
                .then(|| self.actor_ancestry.actor_for_entity(source_entity_uuid))
                .flatten()
                .unwrap_or(key.source_actor_id);
            if self.resolve_owner_actor_id(cohort_provider) != provider_actor_id {
                continue;
            }
            if !cohort_targets.insert(key.target_actor_id) {
                return Err("cohort_target_ambiguous");
            }
            if !self.active_players.contains(&key.target_actor_id) {
                return Err("cohort_target_inactive");
            }
            let class_id = *self
                .class_id_by_actor
                .get(&key.target_actor_id)
                .ok_or("cohort_role_missing")?;
            let role = class_role(class_id)
                .ok()
                .flatten()
                .ok_or("cohort_role_missing")?;
            roles.insert(role);
        }
        if !cohort_targets.contains(&recipient_actor_id) {
            return Err("recipient_cohort_missing");
        }
        let role_delta = i64::try_from(roles.len())
            .ok()
            .and_then(|count| count.checked_mul(config.per_distinct_role_raw_percent_delta))
            .ok_or("role_delta_overflow")?;
        let attack_raw_percent_delta = config
            .base_attack_raw_percent_delta
            .checked_add(role_delta)
            .ok_or("role_delta_overflow")?
            .min(config.maximum_attack_raw_percent_delta);

        let selected = select_damage_stage(
            damage.ability.ok_or("ability_missing")?.0,
            damage.hit_event_id,
            damage.damage_source,
            damage.packet.owner_stage,
            damage.packet.owner_level,
        )
        .ok_or("damage_stage_missing")?;
        let actor_state = self
            .states
            .get(&recipient_actor_id)
            .or_else(|| {
                (recipient_entity_uuid != 0)
                    .then(|| {
                        self.attribute_state_actor_by_entity_uuid
                            .get(&recipient_entity_uuid)
                            .and_then(|actor_id| self.states.get(actor_id))
                    })
                    .flatten()
            })
            .ok_or("recipient_state_missing")?;
        let family = match selected.offensive_stat {
            OffensiveStatKind::PhysicalAttack => &actor_state.physical_attack,
            OffensiveStatKind::MagicalAttack => &actor_state.magical_attack,
        };
        if !family.raw_percent_packet_observed {
            return Err("recipient_attack_not_packet_observed");
        }
        let current_attack = family.final_value.ok_or("attack_family_incomplete")?;
        if family.raw_percent.ok_or("attack_family_incomplete")? < attack_raw_percent_delta {
            return Err("attack_state_excludes_provider_delta");
        }
        let provider_attack_marginal =
            exact_signed_attack_raw_percent_provider_marginal(family, attack_raw_percent_delta)
                .ok_or("attack_family_formula_mismatch")?;
        let contribution = exact_observed_final_attack_stage_contribution(
            observed_micros,
            config.effect_id,
            DamageContributionScope::Component("all-class-aura-observed-final-attack-percent"),
            provider_actor_id,
            recipient_actor_id,
            damage.amount,
            current_attack,
            provider_attack_marginal,
            selected,
        )
        .ok_or("damage_coefficient_counterfactual_unproven")?;
        Ok((contribution, attack_raw_percent_delta))
    }

    fn observed_attack_percent_bucket_contributions(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
        fiery_battle_will: Option<ExactRationalDamageContributionEvent>,
        coordinated_strike: Option<ExactRationalDamageContributionEvent>,
        all_class_aura: Option<(ExactRationalDamageContributionEvent, i64)>,
    ) -> Result<Vec<ExactRationalDamageContributionEvent>, &'static str> {
        let mut weighted = Vec::new();
        if let Some(contribution) = fiery_battle_will {
            weighted.push((
                contribution,
                self.runtime.fiery_battle_will.provider_raw_percent_delta,
            ));
        }
        if let Some(contribution) = coordinated_strike {
            weighted.push((
                contribution,
                self.runtime.coordinated_strike.attack_raw_percent_delta,
            ));
        }
        if let Some((contribution, delta)) = all_class_aura {
            weighted.push((contribution, delta));
        }
        if weighted.len() <= 1 {
            return Ok(weighted
                .into_iter()
                .map(|(contribution, _)| contribution)
                .collect());
        }
        let first = &weighted[0].0;
        if weighted.iter().any(|(contribution, _)| {
            contribution.observed_damage != first.observed_damage
                || contribution.recipient_actor_id != first.recipient_actor_id
                || contribution.observed_damage != damage.amount
        }) {
            return Err("attack_percent_bucket_context_mismatch");
        }
        let selected = select_damage_stage(
            damage.ability.ok_or("ability_missing")?.0,
            damage.hit_event_id,
            damage.damage_source,
            damage.packet.owner_stage,
            damage.packet.owner_level,
        )
        .ok_or("damage_stage_missing")?;
        let actor_state = self
            .states
            .get(&damage.source.actor_id.0)
            .ok_or("recipient_state_missing")?;
        let family = match selected.offensive_stat {
            OffensiveStatKind::PhysicalAttack => &actor_state.physical_attack,
            OffensiveStatKind::MagicalAttack => &actor_state.magical_attack,
        };
        if !family.raw_percent_packet_observed {
            return Err("recipient_attack_not_packet_observed");
        }
        let total_delta = weighted.iter().try_fold(0_i64, |total, (_, delta)| {
            total
                .checked_add(*delta)
                .ok_or("attack_percent_bucket_overflow")
        })?;
        if family.raw_percent.ok_or("attack_family_incomplete")? < total_delta {
            return Err("attack_state_excludes_provider_delta");
        }
        let current_attack = family.final_value.ok_or("attack_family_incomplete")?;
        let joint_marginal = exact_signed_attack_raw_percent_provider_marginal(family, total_delta)
            .ok_or("attack_family_formula_mismatch")?;
        let aggregate = exact_observed_final_attack_stage_contribution(
            observed_micros,
            first.effect_id,
            DamageContributionScope::Component("additive-attack-percent-provider-bucket"),
            first.provider_actor_id,
            first.recipient_actor_id,
            damage.amount,
            current_attack,
            joint_marginal,
            selected,
        )
        .ok_or("damage_coefficient_counterfactual_unproven")?;
        let weights = weighted
            .into_iter()
            .map(|(contribution, delta)| {
                (
                    contribution.effect_id,
                    contribution.provider_actor_id,
                    contribution.scope,
                    delta,
                )
            })
            .collect();
        split_exact_rational_contribution_by_weights(aggregate, weights)
            .ok_or("attack_percent_bucket_split_unproven")
    }

    fn synergy_crit_field_contribution(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Option<ExactRationalDamageContributionEvent> {
        self.synergy_crit_field_decision(observed_micros, damage)
            .ok()
    }

    fn synergy_crit_field_decision(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Result<ExactRationalDamageContributionEvent, &'static str> {
        let config = &self.runtime.synergy_crit_field;
        if !config.runtime_transfer_enabled {
            return Err("runtime_transfer_disabled");
        }
        if damage.amount <= 0 {
            return Err("non_positive_damage");
        }
        if damage.flags.critical != Some(true) {
            return Err("critical_occurrence_missing");
        }
        if damage.flags.lucky != Some(false) {
            return Err("lucky_or_unknown_outcome");
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let target_matches = |target_actor_id: u64| {
            target_actor_id == recipient_actor_id
                || (recipient_entity_uuid != 0
                    && self
                        .attribute_state_entity_uuid_by_actor
                        .get(&target_actor_id)
                        == Some(&recipient_entity_uuid))
        };
        if self
            .formula_status_prior_values_current_wire
            .keys()
            .any(|key| key.effect_id == config.effect_id && target_matches(key.target_actor_id))
        {
            return Err("same_wire_transition");
        }

        // Multiple refreshed instances from the same stable provider are one
        // aura. Different providers are intentionally not stacked or split:
        // the description gives no ordered multi-owner allocation rule.
        let mut providers = BTreeMap::new();
        for (key, value) in self.formula_statuses.iter().filter(|(key, value)| {
            key.effect_id == config.effect_id
                && target_matches(key.target_actor_id)
                && value.level == i64::from(config.required_level)
                && value.stacks == i64::from(config.required_stacks)
        }) {
            let Some(window) = self.synergy_crit_field_windows.get(key) else {
                continue;
            };
            if observed_micros <= window.opened_observed_micros
                || observed_micros >= window.expires_at_observed_micros
            {
                continue;
            }
            if key.source_actor_id == 0 {
                return Err("provider_missing");
            }
            let provider_entity_uuid = value.source_entity_uuid.unwrap_or_default();
            let provider_actor_id = (provider_entity_uuid != 0)
                .then(|| self.actor_ancestry.actor_for_entity(provider_entity_uuid))
                .flatten()
                .unwrap_or(key.source_actor_id);
            let provider_actor_id = self.resolve_owner_actor_id(provider_actor_id);
            if provider_actor_id == recipient_actor_id
                || (recipient_entity_uuid != 0 && provider_entity_uuid == recipient_entity_uuid)
            {
                return Err("provider_is_recipient");
            }
            if !self.active_players.contains(&provider_actor_id) {
                return Err("provider_inactive");
            }
            let identity = if provider_entity_uuid != 0 {
                (0_u8, i128::from(provider_entity_uuid))
            } else {
                (1_u8, i128::from(provider_actor_id))
            };
            providers.entry(identity).or_insert(provider_actor_id);
        }
        if providers.len() != 1 {
            return Err(if providers.is_empty() {
                "provider_window_missing"
            } else {
                "provider_window_ambiguous"
            });
        }
        let provider_actor_id = *providers.values().next().ok_or("provider_window_missing")?;
        let state = self
            .critical_damage_formula_state(recipient_actor_id, recipient_entity_uuid)
            .ok_or("recipient_state_missing")?;
        let (numerator, denominator) = exact_external_critical_damage_fraction(
            damage.amount,
            state
                .critical_damage_raw
                .ok_or("critical_damage_state_missing")?,
            config.critical_damage_raw_delta,
            self.runtime.critical_damage_factor_interpretation,
        )
        .ok_or("damage_counterfactual_unproven")?;
        Ok(ExactRationalDamageContributionEvent {
            observed_micros,
            effect_id: config.effect_id,
            provider_actor_id,
            recipient_actor_id,
            scope: DamageContributionScope::Component("synergy-crit-field-critical-damage"),
            numerator,
            denominator,
            observed_damage: damage.amount,
            included: true,
            deferred_damage_context: None,
        })
    }

    fn joint_critical_cold_team_luck_contributions(
        &self,
        damage: &rlogs_events::DamageEvent,
        critical_cold: ExactRationalDamageContributionEvent,
        team_luck: ExactRationalDamageContributionEvent,
    ) -> Option<[ExactRationalDamageContributionEvent; 2]> {
        self.joint_critical_cold_team_luck_decision(damage, critical_cold, team_luck)
            .ok()
    }

    /// Orders Inspiration's occurrence chance before Team Luck's outcome
    /// multiplier. The chance provider owns the critical/Lucky occurrences it
    /// creates with every then-active damage component; Team Luck owns its
    /// multiplier only across the chance that remains without Inspiration.
    /// Keeping Inspiration's already-composite marginal and scaling Team Luck
    /// by `(C-dC)/C` removes their shared cross-term exactly once.
    fn joint_inspiration_team_luck_contribution(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
        inspiration: ExactRationalDamageContributionEvent,
        mut team_luck: ExactRationalDamageContributionEvent,
    ) -> Option<ExactRationalDamageContributionEvent> {
        if inspiration.effect_id != self.runtime.inspiration.effect_id
            || team_luck.effect_id != self.runtime.team_luck.effect_id
            || inspiration.recipient_actor_id != team_luck.recipient_actor_id
            || inspiration.observed_damage != team_luck.observed_damage
        {
            return None;
        }
        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let route = &self.runtime.inspiration.combined_critical_lucky_route;
        let exact_windows = self
            .inspiration_windows
            .iter()
            .filter(|(key, window)| {
                (key.target_actor_id == recipient_actor_id
                    || (recipient_entity_uuid != 0
                        && window.target_entity_uuid == recipient_entity_uuid))
                    && window.origin_source_type_id == Some(route.provider_origin_source_type_id)
                    && window.origin_source_config_id
                        == Some(self.runtime.inspiration.source_config_id)
                    && window
                        .expires_at_observed_micros
                        .is_some_and(|expires_at| observed_micros <= expires_at)
            })
            .filter_map(|(key, window)| {
                let source_level = window.source_level?;
                let chance_raw_delta = self
                    .runtime
                    .inspiration
                    .chance_raw_delta_for_effect_level_and_mode(
                        source_level,
                        window.provider_full_bloom,
                    )?;
                let provider_actor_id = self
                    .actor_ancestry
                    .actor_for_entity(window.provider_entity_uuid)
                    .unwrap_or(key.provider_actor_id);
                Some((provider_actor_id, chance_raw_delta))
            })
            .collect::<Vec<_>>();
        let [(provider_actor_id, provider_chance_raw_delta)] = exact_windows.as_slice() else {
            return None;
        };
        if *provider_actor_id != inspiration.provider_actor_id {
            return None;
        }
        let state = self
            .team_luck_state_actor_id(recipient_actor_id, recipient_entity_uuid, false)
            .and_then(|actor_id| self.states.get(&actor_id))?;
        let (current_chance_raw, expected_scope, joint_scope) =
            match (damage.flags.critical, damage.flags.lucky) {
                (Some(true), Some(false)) => (
                    state.critical_chance_raw?,
                    DamageContributionScope::Component("team-luck-critical-damage"),
                    DamageContributionScope::Component(
                        "team-luck-critical-damage-joint-inspiration-ordered",
                    ),
                ),
                (Some(false), Some(true)) => (
                    state.lucky_chance_raw?,
                    DamageContributionScope::Component("team-luck-lucky-damage"),
                    DamageContributionScope::Component(
                        "team-luck-lucky-damage-joint-inspiration-ordered",
                    ),
                ),
                _ => return None,
            };
        if team_luck.scope != expected_scope
            || current_chance_raw <= *provider_chance_raw_delta
            || *provider_chance_raw_delta <= 0
        {
            return None;
        }
        let remaining_chance = current_chance_raw.checked_sub(*provider_chance_raw_delta)?;
        team_luck.numerator = team_luck
            .numerator
            .checked_mul(i128::from(remaining_chance))?;
        team_luck.denominator = team_luck
            .denominator
            .checked_mul(i128::from(current_chance_raw))?;
        team_luck.scope = joint_scope;
        Some(team_luck)
    }

    pub fn critical_cold_team_luck_joint_audit_gate(
        &self,
        damage: &rlogs_events::DamageEvent,
    ) -> &'static str {
        let Ok(critical_cold) =
            self.critical_cold_occurrence_decision(self.latest_observed_micros, damage)
        else {
            return "critical_cold_candidate_missing";
        };
        let Ok(team_luck) = self.team_luck_decision(self.latest_observed_micros, damage) else {
            return "team_luck_candidate_missing";
        };
        match self.joint_critical_cold_team_luck_decision(damage, critical_cold, team_luck) {
            Ok(_) => "joint_emittable",
            Err(gate) => gate,
        }
    }

    fn joint_critical_cold_team_luck_decision(
        &self,
        damage: &rlogs_events::DamageEvent,
        mut critical_cold: ExactRationalDamageContributionEvent,
        mut team_luck: ExactRationalDamageContributionEvent,
    ) -> Result<[ExactRationalDamageContributionEvent; 2], &'static str> {
        if damage.flags.critical != Some(true) {
            return Err("joint_critical_outcome_missing");
        }
        if damage.flags.lucky != Some(false) {
            return Err("joint_lucky_or_unknown_outcome");
        }
        if critical_cold.effect_id != self.runtime.critical_cold.effect_id {
            return Err("joint_critical_cold_effect_mismatch");
        }
        if team_luck.effect_id != self.runtime.team_luck.effect_id {
            return Err("joint_team_luck_effect_mismatch");
        }
        if team_luck.scope != DamageContributionScope::Component("team-luck-critical-damage") {
            return Err("joint_team_luck_scope_mismatch");
        }
        if critical_cold.recipient_actor_id != team_luck.recipient_actor_id {
            return Err("joint_recipient_mismatch");
        }
        if critical_cold.observed_damage != team_luck.observed_damage {
            return Err("joint_observed_damage_mismatch");
        }
        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let state = self
            .critical_cold_formula_state(recipient_actor_id, recipient_entity_uuid)
            .ok_or("joint_recipient_state_missing")?;
        let critical_chance_raw = state
            .critical_chance_raw
            .ok_or("joint_critical_chance_state_missing")?;
        let critical_damage_raw = state
            .critical_damage_raw
            .ok_or("joint_critical_damage_state_missing")?;
        let critical_cold_damage_raw_delta = if self
            .inspiration_recipient_dependency_entities
            .contains(&recipient_entity_uuid)
        {
            self.runtime
                .critical_cold
                .recipient_dependency_critical_damage_raw_delta
        } else {
            0
        };
        if critical_chance_raw < self.runtime.critical_cold.critical_chance_raw_delta {
            return Err("joint_critical_cold_delta_exceeds_chance");
        }
        let critical_bonus = match self.runtime.critical_damage_factor_interpretation {
            CriticalDamageFactorInterpretation::Unresolved => {
                return Err("joint_critical_damage_factor_unresolved");
            }
            CriticalDamageFactorInterpretation::AdditiveBonus => critical_damage_raw,
            CriticalDamageFactorInterpretation::DirectTotal => critical_damage_raw
                .checked_sub(BPSR_FIXED_POINT_SCALE)
                .ok_or("joint_critical_damage_factor_invalid")?,
        };
        if critical_bonus <= 0 {
            return Err("joint_critical_damage_factor_invalid");
        }
        let combined_damage_delta = critical_cold_damage_raw_delta
            .checked_add(self.runtime.team_luck.critical_raw_delta)
            .ok_or("joint_critical_damage_delta_overflow")?;
        if combined_damage_delta > critical_bonus {
            return Err("joint_critical_damage_deltas_exceed_bonus");
        }
        let [critical_cold_fraction, team_luck_fraction] =
            exact_joint_critical_cold_team_luck_fractions(
                damage.amount,
                critical_chance_raw,
                self.runtime.critical_cold.critical_chance_raw_delta,
                self.runtime.critical_cold.critical_chance_cap_raw,
                critical_damage_raw,
                critical_cold_damage_raw_delta,
                self.runtime.team_luck.critical_raw_delta,
                self.runtime.critical_damage_factor_interpretation,
            )
            .ok_or("joint_counterfactual_math_failure")?;
        (critical_cold.numerator, critical_cold.denominator) = critical_cold_fraction;
        critical_cold.scope =
            DamageContributionScope::Component(if critical_cold_damage_raw_delta > 0 {
                "critical-cold-critical-chance-and-lightfall-conversion-joint-team-luck-ordered"
            } else {
                "critical-cold-critical-chance-joint-team-luck-ordered"
            });
        (team_luck.numerator, team_luck.denominator) = team_luck_fraction;
        team_luck.scope = DamageContributionScope::Component(
            "team-luck-critical-damage-joint-critical-cold-ordered",
        );
        Ok([critical_cold, team_luck])
    }

    fn combined_harmony_functional_amp_contributions(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
        functional_amp: ExactRationalDamageContributionEvent,
        harmony_grace: ExactRationalDamageContributionEvent,
    ) -> Option<[ExactRationalDamageContributionEvent; 2]> {
        if functional_amp.observed_damage != damage.amount
            || harmony_grace.observed_damage != damage.amount
            || functional_amp.recipient_actor_id != harmony_grace.recipient_actor_id
            || functional_amp.effect_id != self.runtime.functional_amp.effect_id
            || harmony_grace.effect_id != self.runtime.harmony_grace.effect_id
        {
            return None;
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let selected = select_damage_stage(
            damage.ability?.0,
            damage.hit_event_id,
            damage.damage_source,
            damage.packet.owner_stage,
            damage.packet.owner_level,
        )?;
        let class_id = self.recipient_class_id_for_actor(
            recipient_actor_id,
            &self.runtime.harmony_grace.recipient_rules,
        )?;
        let harmony_rule = self
            .runtime
            .harmony_grace
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == class_id)?;
        if !attack_lane_matches(harmony_rule.attack_lane, selected.offensive_stat) {
            return None;
        }
        let actor_state = self.states.get(&recipient_actor_id)?;
        let family = attack_family_for_lane(actor_state, harmony_rule.attack_lane);
        let active_attack = family.final_value?;
        let intermediate = family.intermediate_value?;
        let base_add = family.base_add?;
        let extra_add = family.extra_add?;
        let raw_percent = family.raw_percent?;
        if packet_attribute_family_value(base_add, raw_percent, 0)? != intermediate
            || packet_attribute_family_value(base_add, raw_percent, extra_add)? != active_attack
        {
            return None;
        }

        let harmony_percent = harmony_rule.primary_percent_raw_delta;
        let harmony_primary = actor_state
            .harmony_primary_by_class
            .get(&harmony_rule.recipient_class_id)?;
        let harmony_witness = self
            .harmony_grace_primary_transition_witness(
                recipient_actor_id,
                harmony_grace.provider_actor_id,
                harmony_primary,
                harmony_percent,
            )
            .ok()?;
        let harmony_base_add = exact_primary_to_attack_provider_base_add_from_witness(
            harmony_primary.final_value?,
            harmony_witness.provider_primary_marginal,
            harmony_rule.primary_to_attack_numerator,
            harmony_rule.primary_to_attack_denominator,
        )?;
        let functional_percent = self.runtime.functional_amp.attack_percent_raw_delta;
        let base_without_harmony = base_add.checked_sub(harmony_base_add)?;
        let percent_without_functional = raw_percent.checked_sub(functional_percent)?;
        let attack_without_harmony =
            packet_attribute_family_value(base_without_harmony, raw_percent, extra_add)?;
        let attack_without_both = packet_attribute_family_value(
            base_without_harmony,
            percent_without_functional,
            extra_add,
        )?;
        if active_attack <= attack_without_harmony || attack_without_harmony <= attack_without_both
        {
            return None;
        }

        let (harmony_numerator, harmony_denominator) =
            exact_external_attack_ordered_stage_fraction(
                damage.amount,
                PacketDamageScriptFamily::StandardAttack,
                active_attack,
                active_attack,
                attack_without_harmony,
                selected.coefficient_basis_points,
                selected.fixed_parameter,
            )?;
        let (functional_numerator, functional_denominator) =
            exact_external_attack_ordered_stage_fraction(
                damage.amount,
                PacketDamageScriptFamily::StandardAttack,
                active_attack,
                attack_without_harmony,
                attack_without_both,
                selected.coefficient_basis_points,
                selected.fixed_parameter,
            )?;

        Some([
            ExactRationalDamageContributionEvent {
                observed_micros,
                effect_id: harmony_grace.effect_id,
                provider_actor_id: harmony_grace.provider_actor_id,
                recipient_actor_id,
                scope: DamageContributionScope::Component("harmony-grace-primary-attack"),
                numerator: harmony_numerator,
                denominator: harmony_denominator,
                observed_damage: damage.amount,
                included: true,
                deferred_damage_context: None,
            },
            ExactRationalDamageContributionEvent {
                observed_micros,
                effect_id: functional_amp.effect_id,
                provider_actor_id: functional_amp.provider_actor_id,
                recipient_actor_id,
                scope: DamageContributionScope::Component("functional-amp-attack-magic"),
                numerator: functional_numerator,
                denominator: functional_denominator,
                observed_damage: damage.amount,
                included: true,
                deferred_damage_context: None,
            },
        ])
    }

    fn target_vulnerability_exact_contribution(
        &self,
        envelope: &EventEnvelope,
        damage: &rlogs_events::DamageEvent,
        rule: &TargetVulnerabilityRdpsRule,
    ) -> Option<ExactDamageContributionEvent> {
        if rule.projection == TargetVulnerabilityProjection::PairedObservedOutput {
            return self.target_vulnerability_paired_contribution(envelope, damage, rule);
        }
        if rule.projection != TargetVulnerabilityProjection::Integer {
            return None;
        }
        if damage.amount <= 0
            || damage.ability.map(|ability| ability.0) != Some(rule.ability_id)
            || damage.hit_event_id != Some(rule.hit_event_id)
            || !rule.required_critical.matches(damage.flags.critical)
            || damage.flags.lucky != Some(rule.required_lucky)
        {
            return None;
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let target_actor_id = damage.target.actor_id.0;
        let (provider_ids, _) = self.target_vulnerability_provider_ids(
            recipient_actor_id,
            target_actor_id,
            rule.effect_id,
        );
        let mut providers = provider_ids.into_iter();
        let provider_actor_id = providers.next()?;
        if providers.next().is_some() {
            return None;
        }

        let current_factor = rule.active_factor()?;
        let amount = exact_additive_fixed_point_marginal_from_observed_output(
            damage.amount,
            current_factor,
            rule.provider_raw_delta,
            rule.fixed_point_rounding()?,
        )?;
        Some(ExactDamageContributionEvent {
            observed_micros: envelope.time.observed_micros,
            effect_id: rule.effect_id,
            provider_actor_id,
            recipient_actor_id,
            scope: DamageContributionScope::Component("target-vulnerability"),
            amount,
            observed_damage: damage.amount,
            included: true,
        })
    }

    fn target_vulnerability_paired_contribution(
        &self,
        envelope: &EventEnvelope,
        damage: &rlogs_events::DamageEvent,
        rule: &TargetVulnerabilityRdpsRule,
    ) -> Option<ExactDamageContributionEvent> {
        let active_observed_damage = rule.active_observed_damage?;
        let inactive_observed_damage = rule.inactive_observed_damage?;
        if damage.amount != active_observed_damage
            || damage.ability.map(|ability| ability.0) != Some(rule.ability_id)
            || damage.hit_event_id != Some(rule.hit_event_id)
            || !rule.required_critical.matches(damage.flags.critical)
            || damage.flags.lucky != Some(rule.required_lucky)
        {
            return None;
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let target_actor_id = damage.target.actor_id.0;
        if self.class_id_by_actor.get(&recipient_actor_id).copied() != rule.required_source_class_id
            || self
                .formula_context_sha256(
                    recipient_actor_id,
                    rule.effect_id,
                    &rule.ignored_context_effect_ids,
                )
                .as_deref()
                != rule.required_source_context_sha256.as_deref()
        {
            return None;
        }
        let target_context = self.formula_context_sha256(
            target_actor_id,
            rule.effect_id,
            &rule.ignored_context_effect_ids,
        )?;
        if !rule
            .allowed_target_context_sha256
            .iter()
            .any(|allowed| allowed == &target_context)
        {
            return None;
        }

        let (provider_ids, _) = self.target_vulnerability_provider_ids(
            recipient_actor_id,
            target_actor_id,
            rule.effect_id,
        );
        let mut providers = provider_ids.into_iter();
        let provider_actor_id = providers.next()?;
        if providers.next().is_some() {
            return None;
        }

        Some(ExactDamageContributionEvent {
            observed_micros: envelope.time.observed_micros,
            effect_id: rule.effect_id,
            provider_actor_id,
            recipient_actor_id,
            scope: DamageContributionScope::Component("target-vulnerability"),
            amount: active_observed_damage.checked_sub(inactive_observed_damage)?,
            observed_damage: damage.amount,
            included: true,
        })
    }

    fn formula_context_sha256(
        &self,
        actor_id: u64,
        excluded_effect_id: i64,
        ignored_effect_ids: &[i64],
    ) -> Option<String> {
        let attributes = self.formula_attributes_by_actor.get(&actor_id)?;
        let mut statuses = self
            .formula_statuses
            .iter()
            .filter(|(key, _)| {
                key.target_actor_id == actor_id
                    && key.effect_id != excluded_effect_id
                    && !ignored_effect_ids.contains(&key.effect_id)
            })
            .map(|(_, value)| *value)
            .collect::<Vec<_>>();
        statuses.sort_unstable();

        let mut hasher = Sha256::new();
        hasher.update(b"rlogs-bpsr-formula-context-v1\0");
        for (attribute_id, value) in attributes {
            if *attribute_id == ATTR_CURRENT_HP {
                continue;
            }
            hasher.update(b"A");
            hasher.update(i64::from(*attribute_id).to_le_bytes());
            hasher.update(value.to_le_bytes());
        }
        for status in statuses {
            hasher.update(b"S");
            hasher.update(status.effect_id.to_le_bytes());
            hasher.update(status.stacks.to_le_bytes());
            hasher.update(status.level.to_le_bytes());
        }
        Some(format!("sha256:{:x}", hasher.finalize()))
    }

    fn remote_harmony_source_damage_context_sha256(&self, actor_id: u64) -> Option<String> {
        let runtime = &self.runtime.harmony_grace;
        self.remote_harmony_context_sha256(
            actor_id,
            true,
            true,
            false,
            |attribute_id| {
                // Harmony changes the recipient's main-stat package and its
                // Vitality-derived health family. Season strength, attack
                // speed, and cast speed are independent downstream inputs and
                // must remain exact comparison dimensions.
                !matches!(attribute_id, 11_310..=11_325)
            },
            |effect_id| {
                effect_id != runtime.effect_id
                    && !runtime
                        .remote_paired_output_ignored_effect_ids
                        .contains(&effect_id)
                    && runtime
                        .remote_paired_output_formula_effect_ids
                        .binary_search(&effect_id)
                        .is_ok()
            },
        )
    }

    fn remote_harmony_target_context_sha256(&self, actor_id: u64) -> Option<String> {
        let runtime = &self.runtime.harmony_grace;
        self.remote_harmony_context_sha256(
            actor_id,
            false,
            true,
            false,
            |attribute_id| attribute_id != ATTR_CURRENT_HP,
            |effect_id| effect_id != runtime.effect_id,
        )
    }

    fn remote_fatal_spiral_source_damage_context_sha256(&self, actor_id: u64) -> Option<String> {
        let runtime = &self.runtime.highland_blood;
        let family = &runtime.all_element_family;
        self.remote_harmony_context_sha256(
            actor_id,
            true,
            false,
            true,
            |attribute_id| {
                retained_formula_cohort_attribute(attribute_id)
                    && !matches!(
                        attribute_id,
                        11_310..=11_325 | 11_440 | 11_450 | 11_720 | 11_730
                    )
                    && ![
                        family.current_attribute_id,
                        family.total_attribute_id,
                        family.add_attribute_id,
                        family.extra_add_attribute_id,
                        family.percent_attribute_id,
                        family.extra_percent_attribute_id,
                    ]
                    .contains(&attribute_id)
            },
            |effect_id| {
                effect_id != runtime.effect_id
                    && !runtime
                        .remote_paired_output_ignored_effect_ids
                        .contains(&effect_id)
            },
        )
    }

    fn remote_fatal_spiral_target_context_sha256(&self, actor_id: u64) -> Option<String> {
        let runtime = &self.runtime.highland_blood;
        self.remote_harmony_context_sha256(
            actor_id,
            false,
            false,
            true,
            |attribute_id| {
                retained_formula_cohort_attribute(attribute_id) && attribute_id != ATTR_CURRENT_HP
            },
            |effect_id| effect_id != runtime.effect_id,
        )
    }

    fn remote_harmony_context_sha256(
        &self,
        actor_id: u64,
        attributes_required: bool,
        include_unresolved_status_generation: bool,
        deduplicate_status_values: bool,
        include_attribute: impl Fn(i32) -> bool,
        include_effect: impl Fn(i64) -> bool,
    ) -> Option<String> {
        let attributes = self.formula_attributes_by_actor.get(&actor_id);
        if attributes_required && attributes.is_none() {
            return None;
        }
        let mut statuses = self
            .formula_statuses
            .iter()
            .filter_map(|(key, current)| {
                if key.target_actor_id != actor_id || !include_effect(key.effect_id) {
                    return None;
                }
                match self.formula_status_prior_values_current_wire.get(key) {
                    Some(prior) => *prior,
                    None => Some(*current),
                }
            })
            .collect::<Vec<_>>();
        statuses.extend(
            self.formula_status_prior_values_current_wire
                .iter()
                .filter(|(key, _)| {
                    key.target_actor_id == actor_id
                        && include_effect(key.effect_id)
                        && !self.formula_statuses.contains_key(key)
                })
                .filter_map(|(_, prior)| *prior),
        );
        statuses.sort_unstable();
        if deduplicate_status_values {
            // The sealed proof cohort represents status context as a set of
            // logical values. Repeated wire instances with the same effect,
            // owner, stacks, level, and origin therefore must not split an
            // otherwise identical Fatal Spiral counterfactual group.
            statuses.dedup();
        }

        let mut hasher = Sha256::new();
        hasher.update(b"rlogs-bpsr-remote-harmony-context-v1\0");
        for (attribute_id, value) in attributes.into_iter().flatten() {
            if !include_attribute(*attribute_id) {
                continue;
            }
            hasher.update(b"A");
            hasher.update(i64::from(*attribute_id).to_le_bytes());
            hasher.update(value.to_le_bytes());
        }
        for status in statuses {
            hasher.update(b"S");
            hasher.update(status.effect_id.to_le_bytes());
            update_optional_i64_hash(&mut hasher, status.source_entity_uuid);
            hasher.update(status.stacks.to_le_bytes());
            hasher.update(status.level.to_le_bytes());
            update_optional_i64_hash(&mut hasher, status.origin_source_type_id.map(i64::from));
            update_optional_i64_hash(&mut hasher, status.origin_source_config_id);
        }
        let mut unresolved_instances = self
            .unresolved_status_windows
            .iter()
            .filter(|window| window.target_actor_id == actor_id)
            .filter_map(|window| window.instance_id)
            .collect::<Vec<_>>();
        unresolved_instances.sort_unstable();
        for instance_id in unresolved_instances {
            // Preserve opaque lifecycle state as an exact comparison
            // dimension. An unchanged keyed unknown therefore cancels across
            // a controlled output pair; a changed one produces a different
            // context hash and cannot be attributed to Harmony.
            hasher.update(b"U");
            hasher.update(instance_id.to_le_bytes());
        }
        if include_unresolved_status_generation {
            hasher.update(b"G");
            hasher.update(
                self.unresolved_status_generation_by_actor
                    .get(&actor_id)
                    .copied()
                    .unwrap_or_default()
                    .to_le_bytes(),
            );
        }
        Some(format!("sha256:{:x}", hasher.finalize()))
    }

    fn formula_context_debug(
        &self,
        actor_id: u64,
        excluded_effect_id: i64,
        ignored_effect_ids: &[i64],
    ) -> (Vec<(i32, i64)>, Vec<FormulaStatusValue>) {
        let attributes = self
            .formula_attributes_by_actor
            .get(&actor_id)
            .into_iter()
            .flat_map(|attributes| attributes.iter())
            .filter(|(attribute_id, _)| **attribute_id != ATTR_CURRENT_HP)
            .map(|(attribute_id, value)| (*attribute_id, *value))
            .collect::<Vec<_>>();
        let mut statuses = self
            .formula_statuses
            .iter()
            .filter(|(key, _)| {
                key.target_actor_id == actor_id
                    && key.effect_id != excluded_effect_id
                    && !ignored_effect_ids.contains(&key.effect_id)
            })
            .map(|(_, value)| *value)
            .collect::<Vec<_>>();
        statuses.sort_unstable();
        (attributes, statuses)
    }

    fn target_vulnerability_rational_contribution(
        &self,
        envelope: &EventEnvelope,
        damage: &rlogs_events::DamageEvent,
        rule: &TargetVulnerabilityRdpsRule,
    ) -> Option<ExactRationalDamageContributionEvent> {
        if rule.projection != TargetVulnerabilityProjection::RationalObservedOutput {
            return None;
        }
        if damage.amount <= 0
            || damage.ability.map(|ability| ability.0) != Some(rule.ability_id)
            || damage.hit_event_id != Some(rule.hit_event_id)
            || !rule.required_critical.matches(damage.flags.critical)
            || damage.flags.lucky != Some(rule.required_lucky)
        {
            return None;
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let target_actor_id = damage.target.actor_id.0;
        let (provider_ids, _) = self.target_vulnerability_provider_ids(
            recipient_actor_id,
            target_actor_id,
            rule.effect_id,
        );
        let mut providers = provider_ids.into_iter();
        let provider_actor_id = providers.next()?;
        if providers.next().is_some() {
            return None;
        }

        Some(ExactRationalDamageContributionEvent {
            observed_micros: envelope.time.observed_micros,
            effect_id: rule.effect_id,
            provider_actor_id,
            recipient_actor_id,
            scope: DamageContributionScope::Component("target-vulnerability"),
            numerator: i128::from(damage.amount)
                .checked_mul(i128::from(rule.provider_raw_delta))?,
            denominator: i128::from(rule.active_factor()?),
            observed_damage: damage.amount,
            included: true,
            deferred_damage_context: None,
        })
    }

    fn poison_explosion_vulnerability_contributions(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Vec<ExactRationalDamageContributionEvent> {
        self.poison_explosion_vulnerability_decision(observed_micros, damage)
            .unwrap_or_default()
    }

    fn poison_explosion_vulnerability_decision(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Result<Vec<ExactRationalDamageContributionEvent>, &'static str> {
        let poison_config = &self.runtime.poison_explosion_vulnerability;
        let celestial_config = &self.runtime.celestial_guardian_vulnerability;
        if !self.runtime_applicable
            || (!poison_config.runtime_transfer_enabled
                && !celestial_config.runtime_transfer_enabled)
        {
            return Err("runtime_mismatch");
        }
        if damage.amount <= 0 {
            return Err("nonpositive_damage");
        }
        let target_actor_id = damage.target.actor_id.0;
        let target_entity_uuid = damage.target.entity_uuid.0;
        if target_actor_id == 0 || target_entity_uuid == 0 {
            return Err("target_identity_missing");
        }
        let recipient_actor_id = self.resolve_owner_actor_id(damage.source.actor_id.0);
        if recipient_actor_id == 0 || !self.active_players.contains(&recipient_actor_id) {
            return Err("recipient_inactive");
        }
        if self
            .unresolved_status_windows
            .iter()
            .any(|window| window.target_actor_id == target_actor_id)
        {
            return Err("unresolved_target_status_overlap");
        }
        if self
            .formula_status_prior_values_current_wire
            .keys()
            .any(|key| {
                key.target_actor_id == target_actor_id
                    && (key.effect_id == poison_config.effect_id
                        || key.effect_id == celestial_config.effect_id)
            })
        {
            return Err("same_wire_transition");
        }
        if self.formula_statuses.keys().any(|key| {
            key.target_actor_id == target_actor_id
                && (poison_config
                    .conflicting_target_effect_ids
                    .contains(&key.effect_id)
                    || celestial_config
                        .conflicting_target_effect_ids
                        .contains(&key.effect_id))
        }) {
            return Err("conflicting_target_vulnerability");
        }

        // The two supported effects share the additive Vulnerability stage.
        // Keying by effect and provider preserves separate ledger components
        // while one denominator conserves every active same-stage magnitude.
        // Celestial Guardian's later Element Resistance reduction cancels from
        // the Vulnerability marginal ratio and is deliberately not credited.
        let mut provider_deltas = BTreeMap::<(i64, u64), (i64, i64)>::new();
        let mut add_matching_windows =
            |effect_id: i64,
             windows: &HashMap<PoisonExplosionWindowKey, PoisonExplosionWindow>|
             -> Result<(), &'static str> {
                for (key, window) in windows.iter().filter(|(key, window)| {
                    (key.target_actor_id == target_actor_id
                        || window.target_entity_uuid == target_entity_uuid)
                        && window.target_entity_uuid == target_entity_uuid
                        && observed_micros > window.opened_observed_micros
                        && observed_micros < window.expires_at_observed_micros
                }) {
                    if !self.active_players.contains(&key.provider_owner_actor_id)
                        || self
                            .actor_ancestry
                            .entity_for_actor(key.provider_owner_actor_id)
                            != Some(window.provider_owner_entity_uuid)
                    {
                        return Err("provider_identity_stale");
                    }
                    let provider_delta = window
                        .basis_points_per_stack
                        .checked_mul(i64::from(window.stacks))
                        .ok_or("provider_delta_overflow")?;
                    if provider_delta <= 0
                        || provider_deltas
                            .insert(
                                (effect_id, key.provider_owner_actor_id),
                                (provider_delta, window.provider_owner_entity_uuid),
                            )
                            .is_some()
                    {
                        return Err("provider_window_ambiguous");
                    }
                }
                Ok(())
            };
        if poison_config.runtime_transfer_enabled {
            add_matching_windows(poison_config.effect_id, &self.poison_explosion_windows)?;
        }
        if celestial_config.runtime_transfer_enabled {
            add_matching_windows(celestial_config.effect_id, &self.celestial_guardian_windows)?;
        }
        if provider_deltas.is_empty() {
            return Err("provider_window_missing");
        }
        let total_delta = provider_deltas
            .values()
            .try_fold(0_i64, |total, (delta, _)| {
                total
                    .checked_add(*delta)
                    .ok_or("vulnerability_stage_overflow")
            })?;
        let denominator = 10_000_i128
            .checked_add(i128::from(total_delta))
            .ok_or("vulnerability_stage_overflow")?;
        if denominator <= 10_000 {
            return Err("invalid_vulnerability_stage");
        }

        let mut contributions = Vec::new();
        for ((effect_id, provider_actor_id), (provider_delta, _)) in provider_deltas {
            if provider_actor_id == recipient_actor_id {
                // Self-applied stacks remain in the complete active-stage
                // denominator but never transfer damage to the same actor.
                continue;
            }
            let numerator = i128::from(damage.amount)
                .checked_mul(i128::from(provider_delta))
                .ok_or("vulnerability_stage_overflow")?;
            if numerator <= 0 {
                return Err("invalid_vulnerability_stage");
            }
            let divisor = greatest_common_divisor(numerator, denominator);
            contributions.push(ExactRationalDamageContributionEvent {
                observed_micros,
                effect_id,
                provider_actor_id,
                recipient_actor_id,
                scope: DamageContributionScope::Component("target-vulnerability"),
                numerator: numerator / divisor,
                denominator: denominator / divisor,
                observed_damage: damage.amount,
                included: true,
                deferred_damage_context: None,
            });
        }
        Ok(contributions)
    }

    fn target_vulnerability_audit_gate(&self, damage: &rlogs_events::DamageEvent) -> &'static str {
        let Ok(catalog) = target_vulnerability_rdps_catalog() else {
            return "ability_mismatch";
        };
        let Some(ability_id) = damage.ability.map(|ability| ability.0) else {
            return "ability_mismatch";
        };
        let rule_indices = catalog.rule_indices_for_ability(ability_id);
        if rule_indices.is_empty() {
            return "ability_mismatch";
        }
        if damage.amount <= 0 {
            return "nonpositive_damage";
        }
        if !rule_indices
            .iter()
            .any(|index| damage.hit_event_id == Some(catalog.rules[*index].hit_event_id))
        {
            return "hit_event_mismatch";
        }
        if !rule_indices.iter().any(|index| {
            let rule = &catalog.rules[*index];
            damage.hit_event_id == Some(rule.hit_event_id)
                && rule.required_critical.matches(damage.flags.critical)
        }) {
            return "critical_flag_mismatch";
        }
        let Some(rule) = rule_indices.iter().find_map(|index| {
            let rule = &catalog.rules[*index];
            (damage.hit_event_id == Some(rule.hit_event_id)
                && rule.required_critical.matches(damage.flags.critical)
                && damage.flags.lucky == Some(rule.required_lucky))
            .then_some(rule)
        }) else {
            return "lucky_flag_mismatch";
        };

        let recipient_actor_id = damage.source.actor_id.0;
        let target_actor_id = damage.target.actor_id.0;
        if rule.projection == TargetVulnerabilityProjection::PairedObservedOutput {
            if damage.amount == rule.inactive_observed_damage.unwrap_or_default() {
                return "paired_inactive_observed_witness";
            }
            if damage.amount != rule.active_observed_damage.unwrap_or_default() {
                return "paired_observed_damage_mismatch";
            }
            if self.class_id_by_actor.get(&recipient_actor_id).copied()
                != rule.required_source_class_id
            {
                return "paired_source_class_mismatch";
            }
            if self
                .formula_context_sha256(
                    recipient_actor_id,
                    rule.effect_id,
                    &rule.ignored_context_effect_ids,
                )
                .as_deref()
                != rule.required_source_context_sha256.as_deref()
            {
                return "paired_source_context_mismatch";
            }
            let target_context = self.formula_context_sha256(
                target_actor_id,
                rule.effect_id,
                &rule.ignored_context_effect_ids,
            );
            if !target_context.as_ref().is_some_and(|context| {
                rule.allowed_target_context_sha256
                    .iter()
                    .any(|allowed| allowed == context)
            }) {
                return "paired_target_context_mismatch";
            }
        }
        let (providers, has_same_wire_provider) = self.target_vulnerability_provider_ids(
            recipient_actor_id,
            target_actor_id,
            rule.effect_id,
        );
        match providers.len() {
            0 => "no_external_active_provider",
            1 if has_same_wire_provider => "candidate_same_wire_provider",
            1 => "candidate_active_window_provider",
            _ => "multiple_external_active_providers",
        }
    }

    fn target_vulnerability_provider_ids(
        &self,
        recipient_actor_id: u64,
        target_actor_id: u64,
        effect_id: i64,
    ) -> (HashSet<u64>, bool) {
        let active_window_providers = self
            .target_vulnerability_windows
            .keys()
            .filter(|key| key.target_actor_id == target_actor_id && key.effect_id == effect_id)
            .map(|key| key.provider_actor_id);
        let transition_providers = self
            .target_vulnerability_transitions
            .iter()
            .filter(|key| key.target_actor_id == target_actor_id && key.effect_id == effect_id)
            .map(|key| key.provider_actor_id)
            .collect::<Vec<_>>();
        let has_same_wire_provider = transition_providers.iter().any(|provider_actor_id| {
            let provider_actor_id = self.resolve_owner_actor_id(*provider_actor_id);
            provider_actor_id != recipient_actor_id
                && self.active_players.contains(&provider_actor_id)
        });
        let providers = active_window_providers
            .chain(transition_providers)
            .map(|provider_actor_id| self.resolve_owner_actor_id(provider_actor_id))
            .filter(|provider_actor_id| *provider_actor_id != recipient_actor_id)
            .filter(|provider_actor_id| self.active_players.contains(provider_actor_id))
            .collect::<HashSet<_>>();
        (providers, has_same_wire_provider)
    }

    pub fn target_vulnerability_audit(&self) -> Option<TargetVulnerabilityAudit> {
        self.last_target_vulnerability_audit
    }

    fn finish_critical_cold_pipeline_audit(&mut self, branch: &'static str) {
        if let Some(detail) = self.last_critical_cold_pipeline_audit.as_mut() {
            detail.push_str("; branch=");
            detail.push_str(branch);
        }
    }

    pub fn critical_cold_pipeline_audit_detail(&self) -> Option<&str> {
        self.last_critical_cold_pipeline_audit.as_deref()
    }

    /// Analysis-only detail for the replay audit. The live projector keeps the
    /// same constant-time attribution path; this merely exposes the retained
    /// target/provider identities when a strict packet candidate is rejected.
    pub fn target_vulnerability_audit_detail(&self, damage: &rlogs_events::DamageEvent) -> String {
        let rule = target_vulnerability_rdps_catalog()
            .ok()
            .and_then(|catalog| {
                catalog
                    .rules
                    .iter()
                    .find(|rule| damage.ability.map(|ability| ability.0) == Some(rule.ability_id))
            });
        let effect_id = rule.map(|rule| rule.effect_id);
        let ignored_effect_ids = rule
            .map(|rule| rule.ignored_context_effect_ids.as_slice())
            .unwrap_or_default();
        let transitions = self
            .target_vulnerability_transitions
            .iter()
            .filter(|key| effect_id == Some(key.effect_id))
            .map(|key| {
                (
                    key.target_actor_id,
                    key.provider_actor_id,
                    self.resolve_owner_actor_id(key.provider_actor_id),
                )
            })
            .collect::<Vec<_>>();
        let windows = self
            .target_vulnerability_windows
            .keys()
            .filter(|key| effect_id == Some(key.effect_id))
            .map(|key| {
                (
                    key.target_actor_id,
                    key.provider_actor_id,
                    self.resolve_owner_actor_id(key.provider_actor_id),
                    key.instance_id,
                )
            })
            .collect::<Vec<_>>();
        let source_context = effect_id.and_then(|effect_id| {
            self.formula_context_sha256(damage.source.actor_id.0, effect_id, ignored_effect_ids)
        });
        let target_context = effect_id.and_then(|effect_id| {
            self.formula_context_sha256(damage.target.actor_id.0, effect_id, ignored_effect_ids)
        });
        let source_state = effect_id.map(|effect_id| {
            self.formula_context_debug(damage.source.actor_id.0, effect_id, ignored_effect_ids)
        });
        let target_state = effect_id.map(|effect_id| {
            self.formula_context_debug(damage.target.actor_id.0, effect_id, ignored_effect_ids)
        });
        format!(
            "effect={effect_id:?} amount={} source={} source_class={:?} source_context={source_context:?} source_state={source_state:?} target={} target_context={target_context:?} target_state={target_state:?} transitions={transitions:?} windows={windows:?}",
            damage.amount,
            damage.source.actor_id.0,
            self.class_id_by_actor.get(&damage.source.actor_id.0),
            damage.target.actor_id.0,
        )
    }

    fn fatal_spiral_direct_contribution(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Option<ExactRationalDamageContributionEvent> {
        self.fatal_spiral_direct_decision(observed_micros, damage)
            .ok()
    }

    fn fatal_spiral_direct_decision(
        &self,
        observed_micros: u64,
        damage: &rlogs_events::DamageEvent,
    ) -> Result<ExactRationalDamageContributionEvent, &'static str> {
        let runtime = &self.runtime.highland_blood;
        if !self.runtime_applicable || !runtime.runtime_transfer_enabled {
            return Err("runtime_mismatch");
        }
        if damage.amount <= 0 {
            return Err("nonpositive_damage");
        }
        let Some(ability_id) = damage.ability.map(|ability| ability.0) else {
            return Err("missing_damage_id");
        };
        if runtime
            .excluded_provider_owned_damage_ids
            .contains(&ability_id)
        {
            return Err("excluded_provider_owned_damage");
        }
        let Some(property) = damage.packet.property else {
            return Err("missing_damage_property");
        };
        if property_damage_final_attribute_id(property).is_none() {
            return Err("non_elemental_damage_property");
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        if !self.active_players.contains(&recipient_actor_id) {
            return Err("recipient_inactive");
        }
        let Some(state_actor_id) = self.fatal_spiral_state_actor_id(damage) else {
            return Err("recipient_state_never_observed");
        };
        if self.current_wire.is_some_and(|wire| {
            self.fatal_spiral_transition_wires
                .get(&recipient_actor_id)
                .or_else(|| self.fatal_spiral_transition_wires.get(&state_actor_id))
                == Some(&wire)
        }) {
            return Err("same_wire_transition");
        }

        let providers = self.fatal_spiral_provider_windows_for_recipient(
            recipient_actor_id,
            recipient_entity_uuid,
            Some(state_actor_id),
        );
        if providers.is_empty() {
            return Err("no_external_active_provider");
        }
        if providers.len() != 1 {
            return Err("multiple_external_active_providers");
        }
        let (provider_actor_id, provider_entity_uuid) = providers[0];
        if self
            .fatal_spiral_ambiguous_provider_entities
            .contains(&provider_entity_uuid)
        {
            return Err("ambiguous_provider_magnitude");
        }
        let Some(&provider_basis_points) = self
            .fatal_spiral_equipped_basis_points_by_entity_uuid
            .get(&provider_entity_uuid)
        else {
            return Err("missing_exact_provider_tier");
        };
        if !runtime
            .packet_proven_raw_deltas
            .contains(&provider_basis_points)
        {
            return Err("unproven_recipient_delta");
        }

        let state = self
            .states
            .get(&state_actor_id)
            .ok_or("recipient_state_never_observed")?;
        if state.all_element.provider_basis_points.len() != 1
            || state
                .all_element
                .provider_basis_points
                .get(&provider_actor_id)
                != Some(&provider_basis_points)
        {
            return Err("recipient_transition_unproven");
        }
        let current_all_element = state
            .all_element
            .current_value
            .ok_or("missing_current_all_element_state")?;
        let current_property_bonus = state
            .element_damage_by_property
            .get(&property)
            .copied()
            .ok_or("missing_current_property_element_state")?;
        let denominator = 10_000_i128
            .checked_add(i128::from(current_all_element))
            .and_then(|value| value.checked_add(i128::from(current_property_bonus)))
            .ok_or("invalid_element_bucket")?;
        let numerator = i128::from(damage.amount)
            .checked_mul(i128::from(provider_basis_points))
            .ok_or("invalid_element_bucket")?;
        if denominator <= 0
            || numerator <= 0
            || numerator
                > i128::from(damage.amount)
                    .checked_mul(denominator)
                    .ok_or("invalid_element_bucket")?
        {
            return Err("invalid_element_bucket");
        }
        let divisor = greatest_common_divisor(numerator, denominator);

        Ok(ExactRationalDamageContributionEvent {
            observed_micros,
            effect_id: runtime.effect_id,
            provider_actor_id,
            recipient_actor_id,
            scope: DamageContributionScope::Component(
                "fatal-spiral-all-plus-property-observed-final",
            ),
            numerator: numerator / divisor,
            denominator: denominator / divisor,
            observed_damage: damage.amount,
            included: true,
            deferred_damage_context: None,
        })
    }

    /// Explain whether Fatal Spiral can use the current-build direct observed-
    /// final ratio, or the disabled paired-output audit lane.
    pub fn fatal_spiral_audit_gate(&self, damage: &rlogs_events::DamageEvent) -> &'static str {
        if self.runtime.highland_blood.runtime_transfer_enabled {
            return match self.fatal_spiral_direct_decision(self.latest_observed_micros, damage) {
                Ok(_) => "emitted",
                Err(gate) => gate,
            };
        }
        if !self.runtime_applicable {
            return "runtime_mismatch";
        }
        if damage.amount <= 0 {
            return "nonpositive_damage";
        }
        let Some(ability_id) = damage.ability.map(|ability| ability.0) else {
            return "missing_damage_id";
        };
        if self
            .runtime
            .highland_blood
            .excluded_provider_owned_damage_ids
            .contains(&ability_id)
        {
            return "excluded_provider_owned_damage";
        }
        let Some(property) = damage.packet.property else {
            return "missing_damage_property";
        };
        if !(1..=8).contains(&property) {
            return "non_elemental_damage_property";
        }

        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let state_actor_id = self.fatal_spiral_state_actor_id(damage);
        let providers = self.fatal_spiral_provider_windows_for_recipient(
            recipient_actor_id,
            recipient_entity_uuid,
            state_actor_id,
        );
        if providers.is_empty() {
            return "no_external_active_provider";
        }
        if providers.len() != 1 {
            return "multiple_external_active_providers";
        }
        let (provider_actor_id, provider_entity_uuid) = providers[0];

        let state_basis_points = state_actor_id
            .and_then(|actor_id| self.states.get(&actor_id))
            .and_then(|state| {
                (state.all_element.provider_basis_points.len() == 1)
                    .then(|| state.all_element.provider_basis_points.iter().next())
                    .flatten()
            })
            .and_then(|(&state_provider, &basis_points)| {
                (state_provider == provider_actor_id).then_some(basis_points)
            });
        if self
            .fatal_spiral_ambiguous_provider_entities
            .contains(&provider_entity_uuid)
        {
            return "ambiguous_provider_magnitude";
        }
        let Some(basis_points) = state_basis_points.or_else(|| {
            self.fatal_spiral_provider_basis_points_by_entity_uuid
                .get(&provider_entity_uuid)
                .copied()
        }) else {
            return "missing_exact_provider_magnitude";
        };
        if !self
            .runtime
            .highland_blood
            .packet_proven_raw_deltas
            .contains(&basis_points)
        {
            return "unproven_recipient_delta";
        }

        if self
            .runtime
            .highland_blood
            .remote_paired_output_runtime_transfer_enabled
        {
            if !self.active_players.contains(&recipient_actor_id) {
                return "recipient_inactive";
            }
            if !self.active_players.contains(&provider_actor_id) {
                return "provider_inactive";
            }
            if select_damage_stage(
                ability_id,
                damage.hit_event_id,
                damage.damage_source,
                damage.packet.owner_stage,
                damage.packet.owner_level,
            )
            .is_none()
            {
                return "missing_damage_stage";
            }
            if self
                .remote_fatal_spiral_source_damage_context_sha256(recipient_actor_id)
                .is_none()
            {
                return "missing_source_formula_context";
            }
            if self
                .remote_fatal_spiral_target_context_sha256(damage.target.actor_id.0)
                .is_none()
            {
                return "missing_target_formula_context";
            }
            return "paired_output_eligible";
        }

        "damage_stage_unproven"
    }

    pub fn fatal_spiral_audit_detail(&self, damage: &rlogs_events::DamageEvent) -> String {
        let recipient_actor_id = damage.source.actor_id.0;
        let recipient_entity_uuid = damage.source.entity_uuid.0;
        let state_actor_id = self.fatal_spiral_state_actor_id(damage);
        let providers = self.fatal_spiral_provider_windows_for_recipient(
            recipient_actor_id,
            recipient_entity_uuid,
            state_actor_id,
        );
        let state_providers = state_actor_id
            .and_then(|actor_id| self.states.get(&actor_id))
            .map(|state| state.all_element.provider_basis_points.clone())
            .unwrap_or_default();
        let state_family = state_actor_id
            .and_then(|actor_id| self.states.get(&actor_id))
            .map(|state| {
                (
                    state.all_element.current_value,
                    state.all_element.total_value,
                    state.all_element.add_value,
                    state.all_element.extra_add_value,
                    state.all_element.percent_value,
                    state.all_element.extra_percent_value,
                )
            });
        let cached_provider_basis_points = providers
            .iter()
            .map(|&(provider_actor_id, provider_entity_uuid)| {
                (
                    provider_actor_id,
                    provider_entity_uuid,
                    self.fatal_spiral_provider_basis_points_by_entity_uuid
                        .get(&provider_entity_uuid)
                        .copied(),
                    self.fatal_spiral_ambiguous_provider_entities
                        .contains(&provider_entity_uuid),
                )
            })
            .collect::<Vec<_>>();
        format!(
            "ability={:?} property={:?} source={} source_entity={} state_actor={state_actor_id:?} target={} window_providers={providers:?} cached_provider_basis_points={cached_provider_basis_points:?} state_provider_basis_points={state_providers:?} all_element_family={state_family:?} amount={}",
            damage.ability.map(|ability| ability.0),
            damage.packet.property,
            recipient_actor_id,
            damage.source.entity_uuid.0,
            damage.target.actor_id.0,
            damage.amount,
        )
    }

    fn fatal_spiral_state_actor_id(&self, damage: &rlogs_events::DamageEvent) -> Option<u64> {
        let recipient_actor_id = damage.source.actor_id.0;
        if self.states.contains_key(&recipient_actor_id) {
            return Some(recipient_actor_id);
        }
        let entity_uuid = damage.source.entity_uuid.0;
        (entity_uuid != 0)
            .then(|| {
                self.attribute_state_actor_by_entity_uuid
                    .get(&entity_uuid)
                    .copied()
            })
            .flatten()
    }

    fn fatal_spiral_provider_windows_for_recipient(
        &self,
        recipient_actor_id: u64,
        recipient_entity_uuid: i64,
        state_actor_id: Option<u64>,
    ) -> Vec<(u64, i64)> {
        let mut providers = self
            .fatal_spiral_windows
            .iter()
            .filter(|key| {
                key.target_actor_id == recipient_actor_id
                    || state_actor_id == Some(key.target_actor_id)
                    || (recipient_entity_uuid != 0
                        && key.target_entity_uuid == recipient_entity_uuid)
            })
            .map(|key| {
                (
                    self.resolve_owner_actor_id(key.provider_actor_id),
                    key.provider_entity_uuid,
                )
            })
            .filter(|(provider_actor_id, _)| *provider_actor_id != recipient_actor_id)
            .filter(|(provider_actor_id, _)| self.active_players.contains(provider_actor_id))
            .collect::<Vec<_>>();
        providers.sort_unstable();
        providers.dedup();
        providers
    }

