    fn harmony_grace_window_gate(
        &self,
        key: &EffectWindowKey,
        observed_micros: u64,
    ) -> Result<(), &'static str> {
        let timing = self
            .harmony_grace_window_timing
            .get(key)
            .ok_or("harmony_lifecycle_timestamp_missing")?;
        if observed_micros <= timing.opened_observed_micros {
            return Err("harmony_lifecycle_order_unresolved");
        }
        let duration_millis = timing
            .duration_millis
            .ok_or("harmony_lifecycle_duration_missing")?;
        let elapsed_micros = observed_micros - timing.opened_observed_micros;
        if u128::from(elapsed_micros) >= u128::from(duration_millis) * 1_000 {
            return Err("harmony_lifecycle_expired");
        }
        Ok(())
    }

    fn expire_harmony_grace_windows(&mut self, observed_micros: u64) {
        let expired = self
            .harmony_grace_window_timing
            .iter()
            .filter(|(_, timing)| {
                observed_micros >= timing.opened_observed_micros
                    && timing.duration_millis.is_some_and(|duration_millis| {
                        u128::from(observed_micros - timing.opened_observed_micros)
                            >= u128::from(duration_millis) * 1_000
                    })
            })
            .map(|(key, _)| *key)
            .collect::<Vec<_>>();
        let mut expired_targets = HashSet::new();
        for key in expired {
            self.harmony_grace_windows.remove(&key);
            self.harmony_grace_window_timing.remove(&key);
            self.harmony_grace_primary_transition_witnesses.remove(&key);
            expired_targets.insert(key.target_actor_id);
        }
        for target_actor_id in expired_targets {
            // Duration expiry is authoritative lifecycle closure, but unlike
            // an explicit terminal packet it may not carry the reverse
            // attribute vector. Reconcile any packet transition available on
            // this wire, then discard stale provider ownership rather than
            // letting it contaminate a later application or provider rotation.
            self.reconcile_harmony_grace_staged_state(target_actor_id);
            for state in [&mut self.states, &mut self.staged_states] {
                if let Some(state) = state.get_mut(&target_actor_id) {
                    for family in state.harmony_primary_by_class.values_mut() {
                        family.provider_raw_percent.clear();
                    }
                }
            }
            if let Some(wire) = self.current_wire {
                self.harmony_grace_transition_wires
                    .insert(target_actor_id, wire);
            }
        }
    }

    fn clear_actor(&mut self, actor_id: u64) {
        self.unresolved_status_windows
            .retain(|window| window.target_actor_id != actor_id);
        self.unresolved_status_generation_by_actor.remove(&actor_id);
        self.states.remove(&actor_id);
        self.staged_states.remove(&actor_id);
        self.team_luck_critical_ever_observed.remove(&actor_id);
        self.team_luck_lucky_ever_observed.remove(&actor_id);
        self.team_luck_critical_cleared_by_snapshot
            .remove(&actor_id);
        self.team_luck_lucky_cleared_by_snapshot.remove(&actor_id);
        self.incomplete_rdps_actor_ids.remove(&actor_id);
        self.life_wave_character_id_by_actor.remove(&actor_id);
        if let Some(entity_uuid) = self.life_wave_entity_uuid_by_actor.remove(&actor_id) {
            self.life_wave_bonus_basis_points_by_entity_uuid
                .remove(&entity_uuid);
        }
        self.life_wave_windows
            .retain(|key, _| key.target_actor_id != actor_id);
        self.pending_life_wave_activations
            .retain(|key, _| key.target_actor_id != actor_id);
        self.life_wave_heal_providers_current_wire
            .retain(|(target_actor_id, _), providers| {
                providers.remove(&actor_id);
                *target_actor_id != actor_id
            });
        if let Some(entity_uuid) = self.attribute_state_entity_uuid_by_actor.remove(&actor_id) {
            if self.attribute_state_actor_by_entity_uuid.get(&entity_uuid) == Some(&actor_id) {
                self.attribute_state_actor_by_entity_uuid
                    .remove(&entity_uuid);
            }
        }
        self.effect_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.team_luck_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.team_luck_transition_wires.remove(&actor_id);
        self.functional_amp_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.functional_amp_transition_wires.remove(&actor_id);
        self.mechanical_power_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.mechanical_power_transition_wires.remove(&actor_id);
        self.mechanical_power_primary_transition_witnesses
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.harmony_grace_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.harmony_grace_window_timing
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.harmony_grace_transition_wires.remove(&actor_id);
        self.harmony_grace_primary_transition_witnesses
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.stat_resonance_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.stat_resonance_transition_wires.remove(&actor_id);
        self.stat_resonance_pending_transitions.remove(&actor_id);
        self.stat_resonance_attack_witnesses
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.fiery_battle_will_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.fiery_battle_will_transition_wires.remove(&actor_id);
        self.fiery_battle_will_pending_transitions.remove(&actor_id);
        self.fiery_battle_will_attack_witnesses
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.encore_windows.retain(|key| {
            // Encore (55333) lives on the recipient. A provider actor despawn
            // does not terminate that server-owned status or erase the stable
            // provider entity captured at application time. Recipient despawn,
            // an exact status terminal, or a TCP gap still fails closed.
            key.target_actor_id != actor_id
        });
        self.thunder_roar_windows.retain(|key, window| {
            // The recipient-held lifecycle survives a source proxy despawn;
            // its player owner was snapped at application. Recipient despawn
            // remains an exact terminal for attribution state.
            key.target_actor_id != actor_id && window.provider_owner_actor_id != actor_id
        });
        self.thunderwind_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.thunderwind_child_targets.remove(&actor_id);
        self.thunderwind_transition_wires.remove(&actor_id);
        // Full Bloom ownership is keyed by stable entity UUID and survives an
        // actor-id rotation. Exact terminal, expiry, TCP gap, or run boundary
        // clears the lifecycle.
        self.inspiration_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.endless_mind_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.endless_mind_transition_wires.remove(&actor_id);
        self.arcane_time_decree_windows
            .retain(|key, _| key.target_actor_id != actor_id);
        self.arcane_time_decree_transition_wires.remove(&actor_id);
        self.cooldown_action_state
            .retain(|(cooldown_actor_id, _), _| *cooldown_actor_id != actor_id);
        self.inspire_haste_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.inspire_haste_transition_wires.remove(&actor_id);
        // Critical Cold (talent 250; child status 2204471, design name
        // 暴击之寒_队友暴击) is keyed by stable provider and recipient entity
        // UUIDs. Actor-id rotation on either side does not terminate the
        // exact recipient-held lifecycle; terminal status, TCP gap, or run
        // boundary does.
        self.critical_cold_transition_wires.remove(&actor_id);
        // Lightfall (talent 1122), status 2203220 (`暴击双生`), is keyed by
        // stable recipient entity UUID and survives actor-id rotation. Its
        // own terminal lifecycle, TCP gap, or run boundary clears it.
        self.inspiration_transition_wires.remove(&actor_id);
        self.inspiration_snapshot_targets.remove(&actor_id);
        self.fatal_spiral_windows
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.fatal_spiral_transition_wires.remove(&actor_id);
        self.fatal_spiral_transitions.remove(&actor_id);
        self.fatal_spiral_snapshot_targets.remove(&actor_id);
        self.target_vulnerability_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.target_vulnerability_transitions
            .retain(|key| key.target_actor_id != actor_id && key.provider_actor_id != actor_id);
        self.poison_explosion_windows.retain(|key, _| {
            key.target_actor_id != actor_id && key.provider_owner_actor_id != actor_id
        });
        self.celestial_guardian_windows.retain(|key, _| {
            key.target_actor_id != actor_id && key.provider_owner_actor_id != actor_id
        });
        self.formula_attributes_by_actor.remove(&actor_id);
        self.synergy_crit_field_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.element_sharing_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.enhanced_synergy_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.blessing_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.synergy_luck_field_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.coordinated_strike_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.all_class_aura_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.attribute_transfer_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.tactical_blessing_windows
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.formula_statuses
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.formula_status_prior_values_current_wire
            .retain(|key, _| key.target_actor_id != actor_id && key.source_actor_id != actor_id);
        self.entity_type_by_actor.remove(&actor_id);
        self.summon_config_by_actor.remove(&actor_id);
        self.class_id_by_actor.remove(&actor_id);
        self.specialization_id_by_actor.remove(&actor_id);
        self.observed_ability_ids_by_actor.remove(&actor_id);
    }

