    #[test]
    fn inspiration_occurrence_dispatch_preserves_each_proven_chance_stage() {
        let observed_damage = 987_654;
        let critical_chance = 7_416;
        let lucky_chance = 800;
        let provider_delta = 300;
        let critical_damage = 15_000;

        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                true,
                false,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                None,
                None,
                None,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            exact_external_critical_chance_fraction(
                observed_damage,
                critical_chance,
                provider_delta,
                critical_damage,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            )
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                true,
                true,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                Some(150),
                Some(4_200),
                Some(75),
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            exact_external_combined_critical_lucky_chance_and_damage_fraction(
                observed_damage,
                critical_chance,
                provider_delta,
                lucky_chance,
                provider_delta,
                critical_damage,
                150,
                4_200,
                75,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            "combined rows must remove chance, Crit-DMG, and Lucky-DMG cross-terms exactly once",
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                false,
                true,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                None,
                Some(4_200),
                None,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            exact_external_lucky_chance_fraction(observed_damage, lucky_chance, provider_delta,)
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                false,
                true,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                None,
                Some(4_200),
                Some(75),
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            exact_external_lucky_chance_and_damage_fraction(
                observed_damage,
                lucky_chance,
                provider_delta,
                4_200,
                75,
            ),
            "base Luck conversion must compose chance and Lucky-DMG as one marginal",
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                true,
                true,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                None,
                Some(4_200),
                None,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            crate::exact_external_combined_critical_lucky_chance_fraction(
                observed_damage,
                critical_chance,
                provider_delta,
                lucky_chance,
                provider_delta,
                critical_damage,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            )
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                false,
                false,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                None,
                None,
                None,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            None
        );
        assert_eq!(
            exact_inspiration_occurrence_fraction(
                observed_damage,
                true,
                false,
                critical_chance,
                lucky_chance,
                provider_delta,
                critical_damage,
                Some(600),
                None,
                None,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            exact_external_critical_chance_and_damage_fraction(
                observed_damage,
                critical_chance,
                provider_delta,
                critical_damage,
                600,
                CriticalDamageFactorInterpretation::AdditiveBonus,
            ),
            "recipient-build Crit chance to Crit DMG conversion must be composed as one provider marginal",
        );
    }

