    #[test]
    fn harmony_grace_missing_duration_is_retained_unresolved_on_the_shared_runtime_path() {
        let mut projector =
            BpsrStateDamageContributionProjector::new_harmony_grace_candidate_audit()
                .expect("Harmony Grace candidate audit should validate");
        projector.active_players.extend([2, 4]);
        let applied = harmony_grace_wire_envelope(
            1,
            1_000,
            harmony_grace_status_event(2, 4, 11, StatusState::Applied, None),
        );
        assert!(observe_harmony_grace_test_envelope(&mut projector, &applied).is_empty());
        let window = EffectWindowKey {
            target_actor_id: 4,
            provider_actor_id: 2,
            instance_id: Some(11),
        };
        assert!(projector.harmony_grace_windows.contains(&window));
        assert_eq!(
            projector
                .harmony_grace_window_timing
                .get(&window)
                .and_then(|timing| timing.duration_millis),
            None
        );

        let damage = harmony_grace_wire_envelope(2, 2_000, harmony_grace_damage_event(4));
        assert!(observe_harmony_grace_test_envelope(&mut projector, &damage).is_empty());
        assert!(
            projector.harmony_grace_windows.contains(&window),
            "duration-less evidence remains available for a later explicit terminal"
        );
        assert!(projector.incomplete_rdps_actor_ids.contains(&2));
        assert!(projector.incomplete_rdps_actor_ids.contains(&4));
    }

    #[test]
    fn harmony_grace_equal_time_refresh_damage_is_unresolved_on_the_shared_runtime_path() {
        let mut projector =
            BpsrStateDamageContributionProjector::new_harmony_grace_candidate_audit()
                .expect("Harmony Grace candidate audit should validate");
        projector.active_players.extend([2, 4]);
        for envelope in [
            harmony_grace_wire_envelope(
                1,
                1_000,
                harmony_grace_status_event(2, 4, 11, StatusState::Applied, Some(8_000)),
            ),
            harmony_grace_wire_envelope(
                2,
                2_000,
                harmony_grace_status_event(2, 4, 11, StatusState::Refreshed, Some(8_000)),
            ),
        ] {
            assert!(observe_harmony_grace_test_envelope(&mut projector, &envelope).is_empty());
        }

        let damage = harmony_grace_wire_envelope(3, 2_000, harmony_grace_damage_event(4));
        assert!(observe_harmony_grace_test_envelope(&mut projector, &damage).is_empty());
        assert!(projector.incomplete_rdps_actor_ids.contains(&2));
        assert!(projector.incomplete_rdps_actor_ids.contains(&4));
        assert_eq!(
            projector
                .harmony_grace_window_timing
                .values()
                .next()
                .map(|timing| timing.opened_observed_micros),
            Some(2_000)
        );
    }

    #[test]
    fn harmony_grace_expiry_cleans_provider_state_before_rotation_on_the_shared_runtime_path() {
        let mut projector = BpsrStateDamageContributionProjector::default();
        let applied = harmony_grace_wire_envelope(
            1,
            1_000,
            harmony_grace_status_event(2, 4, 11, StatusState::Applied, Some(1)),
        );
        assert!(observe_harmony_grace_test_envelope(&mut projector, &applied).is_empty());
        let recipient_rule = runtime()
            .harmony_grace
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == 11)
            .unwrap();
        let attributed_family = AttackFamilyState {
            raw_percent: Some(1_700),
            provider_raw_percent: BTreeMap::from([(2, recipient_rule.primary_percent_raw_delta)]),
            ..AttackFamilyState::default()
        };
        let attributed_state = ActorHpState {
            harmony_primary_by_class: BTreeMap::from([(
                recipient_rule.recipient_class_id,
                attributed_family,
            )]),
            ..ActorHpState::default()
        };
        projector.states.insert(4, attributed_state.clone());
        projector.staged_states.insert(4, attributed_state);

        let damage = harmony_grace_wire_envelope(2, 2_000, harmony_grace_damage_event(4));
        assert!(observe_harmony_grace_test_envelope(&mut projector, &damage).is_empty());
        assert!(projector.harmony_grace_windows.is_empty());
        assert!(projector.harmony_grace_window_timing.is_empty());
        assert!(projector.states.contains_key(&4));
        assert!(
            projector
                .states
                .get(&4)
                .into_iter()
                .chain(projector.staged_states.get(&4))
                .flat_map(|state| state.harmony_primary_by_class.values())
                .all(|family| family.provider_raw_percent.is_empty()),
            "duration expiry must invalidate stale provider decomposition"
        );

        let rotated = harmony_grace_wire_envelope(
            3,
            3_000,
            harmony_grace_status_event(3, 4, 12, StatusState::Applied, Some(1)),
        );
        assert!(observe_harmony_grace_test_envelope(&mut projector, &rotated).is_empty());
        assert_eq!(projector.harmony_grace_windows.len(), 1);
        assert!(
            projector
                .harmony_grace_windows
                .iter()
                .all(|window| { window.provider_actor_id == 3 && window.target_actor_id == 4 })
        );
        assert!(
            projector
                .states
                .get(&4)
                .into_iter()
                .chain(projector.staged_states.get(&4))
                .flat_map(|state| state.harmony_primary_by_class.values())
                .all(|family| !family.provider_raw_percent.contains_key(&2))
        );
    }

    #[test]
    fn mechanical_power_reconciles_attributes_that_precede_status_on_the_same_wire() {
        let recipient_rule = runtime()
            .mechanical_power
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == 11)
            .unwrap();
        let candidate_primary_percent_raw_delta = 750;
        let first_wire = WireKey {
            connection_id: 1,
            stream_id: 2,
            capture_sequence: 3,
        };
        let inactive_primary = AttackFamilyState {
            final_value: Some(10_465),
            intermediate_value: Some(7_405),
            base_add: Some(6_120),
            extra_add: Some(3_060),
            raw_percent: Some(2_100),
            raw_percent_packet_observed: true,
            provider_raw_percent: BTreeMap::new(),
        };
        let active_primary = AttackFamilyState {
            final_value: Some(10_924),
            intermediate_value: Some(7_864),
            base_add: Some(6_120),
            extra_add: Some(3_060),
            raw_percent: Some(2_850),
            raw_percent_packet_observed: true,
            provider_raw_percent: BTreeMap::new(),
        };
        let mut projector = BpsrStateDamageContributionProjector {
            mechanical_power_candidate_audit_enabled: true,
            mechanical_power_candidate_primary_percent_override: Some(
                candidate_primary_percent_raw_delta,
            ),
            current_wire: Some(first_wire),
            states: HashMap::from([(
                4,
                ActorHpState {
                    mechanical_primary_by_class: BTreeMap::from([(
                        recipient_rule.recipient_class_id,
                        inactive_primary.clone(),
                    )]),
                    ..ActorHpState::default()
                },
            )]),
            staged_states: HashMap::from([(
                4,
                ActorHpState {
                    mechanical_primary_by_class: BTreeMap::from([(
                        recipient_rule.recipient_class_id,
                        active_primary,
                    )]),
                    ..ActorHpState::default()
                },
            )]),
            class_id_by_actor: HashMap::from([(4, recipient_rule.recipient_class_id)]),
            active_players: HashSet::from([2, 4]),
            ..BpsrStateDamageContributionProjector::default()
        };
        let mut status = rlogs_events::StatusEvent {
            source: Some(rlogs_events::EntityRef {
                actor_id: rlogs_events::ActorId(2),
                entity_uuid: rlogs_events::EntityUuid(20),
            }),
            target: rlogs_events::EntityRef {
                actor_id: rlogs_events::ActorId(4),
                entity_uuid: rlogs_events::EntityUuid(40),
            },
            effect: rlogs_events::StatusEffectId(runtime().mechanical_power.effect_id),
            instance_id: Some(rlogs_events::StatusEffectInstanceId(11)),
            origin: None,
            state: StatusState::Applied,
            stacks: Some(1),
            level: Some(5),
            part_id: None,
            count: None,
            created_at_millis: None,
            duration_millis: Some(runtime().mechanical_power.duration_millis),
        };

        projector.observe_mechanical_power_status(&status);
        let desired = BTreeMap::from([(2, candidate_primary_percent_raw_delta)]);
        assert_eq!(
            projector.staged_states[&4].mechanical_primary_by_class
                [&recipient_rule.recipient_class_id]
                .provider_raw_percent,
            desired
        );
        let window = EffectWindowKey {
            target_actor_id: 4,
            provider_actor_id: 2,
            instance_id: Some(11),
        };
        let witness = projector.mechanical_power_primary_transition_witnesses[&window]
            .iter()
            .next()
            .unwrap();
        assert_eq!(witness.wire, first_wire);
        assert_eq!(witness.provider_primary_marginal, 459);

        let second_wire = WireKey {
            capture_sequence: 4,
            ..first_wire
        };
        projector.advance_wire(second_wire);
        assert_eq!(
            projector.states[&4].mechanical_primary_by_class[&recipient_rule.recipient_class_id]
                .provider_raw_percent,
            desired
        );

        projector.staged_states.insert(
            4,
            ActorHpState {
                mechanical_primary_by_class: BTreeMap::from([(
                    recipient_rule.recipient_class_id,
                    inactive_primary,
                )]),
                ..ActorHpState::default()
            },
        );
        status.state = StatusState::Removed;
        status.stacks = Some(0);
        projector.observe_mechanical_power_status(&status);
        assert!(
            projector.staged_states[&4].mechanical_primary_by_class
                [&recipient_rule.recipient_class_id]
                .provider_raw_percent
                .is_empty()
        );
        assert!(
            !projector
                .mechanical_power_primary_transition_witnesses
                .contains_key(&window),
            "closing the lifecycle must remove its transition witness"
        );
    }

    #[test]
    fn harmony_grace_reconciles_every_listed_primary_family_without_a_class_gate() {
        let runtime = rdps_runtime_config().expect("current runtime should validate");
        let physical_rule = runtime
            .harmony_grace
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == 11)
            .cloned()
            .expect("physical recipient route");
        let magical_rule = runtime
            .harmony_grace
            .recipient_rules
            .iter()
            .find(|rule| rule.recipient_class_id == 2)
            .cloned()
            .expect("magical recipient route");
        let previous_family = AttackFamilyState {
            raw_percent: Some(1_500),
            ..AttackFamilyState::default()
        };
        let current_family = AttackFamilyState {
            raw_percent: Some(1_700),
            ..AttackFamilyState::default()
        };
        let previous = ActorHpState {
            harmony_primary_by_class: BTreeMap::from([
                (physical_rule.recipient_class_id, previous_family.clone()),
                (magical_rule.recipient_class_id, previous_family),
            ]),
            ..ActorHpState::default()
        };
        let staged = ActorHpState {
            harmony_primary_by_class: BTreeMap::from([
                (physical_rule.recipient_class_id, current_family.clone()),
                (magical_rule.recipient_class_id, current_family),
            ]),
            ..ActorHpState::default()
        };
        let mut projector = BpsrStateDamageContributionProjector {
            states: HashMap::from([(4, previous)]),
            staged_states: HashMap::from([(4, staged)]),
            // Intentionally omit class identity. Harmony's application has no
            // class condition; only later damage conversion needs this.
            class_id_by_actor: HashMap::new(),
            ..BpsrStateDamageContributionProjector::default()
        };
        let status = rlogs_events::StatusEvent {
            source: Some(rlogs_events::EntityRef {
                actor_id: rlogs_events::ActorId(2),
                entity_uuid: rlogs_events::EntityUuid(20),
            }),
            target: rlogs_events::EntityRef {
                actor_id: rlogs_events::ActorId(4),
                entity_uuid: rlogs_events::EntityUuid(40),
            },
            effect: rlogs_events::StatusEffectId(runtime.harmony_grace.effect_id),
            instance_id: Some(rlogs_events::StatusEffectInstanceId(11)),
            origin: None,
            state: StatusState::Applied,
            stacks: Some(1),
            level: None,
            part_id: None,
            count: None,
            created_at_millis: None,
            duration_millis: Some(8_000),
        };

        projector.observe_harmony_grace_status(&status, 1);

        for recipient_rule in [&physical_rule, &magical_rule] {
            assert_eq!(
                projector.staged_states[&4].harmony_primary_by_class
                    [&recipient_rule.recipient_class_id]
                    .provider_raw_percent,
                BTreeMap::from([(2, recipient_rule.primary_percent_raw_delta)]),
                "Harmony must apply to every listed primary family before class selection"
            );
        }
    }

